    for v in self.validators:
        try:
            v(inst, attr, value)
        except Exception:  # noqa: BLE001, PERF203, S112
            continue
        else:
            return

    msg = f"None of {self.validators!r} satisfied for value {value!r}"
    raise ValueError(msg)

