    try:
        self.validator(inst, attr, value)
    except self.exc_types:
        pass  # suppress error to invert validity
    else:
        raise ValueError(
            self.msg.format(
                validator=self.validator,
                exc_types=self.exc_types,
            ),
            attr,
            self.validator,
            value,
            self.exc_types,
        )

