    try:
        a, hook, is_gen = sa_attrs[name]
    except KeyError:
        _OBJ_SETATTR(self, name, val)

        return

    if is_gen():
        gen = hook(self, a, val)
        nval = next(gen)
        _OBJ_SETATTR(self, name, nval)
        try:
            next(gen)
        except StopIteration:
            return

        gen.close()
        msg = "Generator on_setattr hook yielded more than once."
        raise RuntimeError(msg)

    nval = hook(self, a, val)
    _OBJ_SETATTR(self, name, nval)

    return

