def is_gen() -> bool:
    import inspect

    try:
        if f not in _IS_GENERATOR_RESULTS:
            _IS_GENERATOR_RESULTS[f] = inspect.isgeneratorfunction(f)
    except TypeError:  # f is not hashable
        return inspect.isgeneratorfunction(f)

    return _IS_GENERATOR_RESULTS[f]

