def update(self, E, **F):
    """Add items from a dictionary or iterable (and/or keyword arguments),
    overwriting values under an existing key. See
    :meth:`dict.update` for more details.
    """
    # E and F are throwback names to the dict() __doc__
    if E is self:
        return
    self_add = self.add
    if isinstance(E, OrderedMultiDict):
        for k in E:
            if k in self:
                del self[k]
        for k, v in E.iteritems(multi=True):
            self_add(k, v)
    elif callable(getattr(E, 'keys', None)):
        for k in E.keys():
            self[k] = E[k]
    else:
        seen = set()
        seen_add = seen.add
        for k, v in E:
            if k not in seen:
                if k in self:
                    del self[k]
                seen_add(k)
            self_add(k, v)
    for k in F:
        self[k] = F[k]
    return

