    else:
        self._dst_offset = self._std_offset

    self._dst_saved = self._dst_offset - self._std_offset
    self._hasdst = bool(self._dst_saved)
    self._tznames = tuple(time.tzname)

def _validate_fromutc_inputs(f):
    """
    The CPython version of ``fromutc`` checks that the input is a ``datetime``
    object and that ``self`` is attached as its ``tzinfo``.
    """
    @wraps(f)
    def fromutc(self, dt):
        if not isinstance(dt, datetime):
            raise TypeError("fromutc() requires a datetime argument")
        if dt.tzinfo is not self:
            raise ValueError("dt.tzinfo is not self")

        return f(self, dt)

    return fromutc

def __init__(self, stdabbr, stdoffset=None,
             dstabbr=None, dstoffset=None,
             start=None, end=None):

    global relativedelta
    from dateutil import relativedelta

    self._std_abbr = stdabbr
    self._dst_abbr = dstabbr

    try:
        stdoffset = stdoffset.total_seconds()
    except (TypeError, AttributeError):
        pass

    try:
        dstoffset = dstoffset.total_seconds()
    except (TypeError, AttributeError):
        pass

    if stdoffset is not None:
        self._std_offset = datetime.timedelta(seconds=stdoffset)
    else:
        self._std_offset = ZERO

    if dstoffset is not None:
        self._dst_offset = datetime.timedelta(seconds=dstoffset)
    elif dstabbr and stdoffset is not None:
        self._dst_offset = self._std_offset + datetime.timedelta(hours=+1)
    else:
        self._dst_offset = ZERO

    if dstabbr and start is None:
        self._start_delta = relativedelta.relativedelta(
            hours=+2, month=4, day=1, weekday=relativedelta.SU(+1))
    else:
        self._start_delta = start

    if dstabbr and end is None:
        self._end_delta = relativedelta.relativedelta(
            hours=+1, month=10, day=31, weekday=relativedelta.SU(-1))
    else:
        self._end_delta = end

    self._dst_base_offset_ = self._dst_offset - self._std_offset
    self.hasdst = bool(self._start_delta)

def _parse_tzstr(self, tzstr, zero_as_utc=True):
    if tzstr == b'Z' or tzstr == b'z':
        return tz.UTC

    if len(tzstr) not in {3, 5, 6}:
        raise ValueError('Time zone offset must be 1, 3, 5 or 6 characters')

    if tzstr[0:1] == b'-':
        mult = -1
    elif tzstr[0:1] == b'+':
        mult = 1
    else:
        raise ValueError('Time zone offset requires sign')

    hours = self._parse_digits(tzstr, 1, 2)
    if len(tzstr) == 3:
        minutes = 0
    else:
        pos = 4 if tzstr[3:4] == self._TIME_SEP else 3
        if len(tzstr) != pos + 2:
            raise ValueError("Invalid minutes in time zone offset")
        minutes = self._parse_digits(tzstr, pos, 2)

    if zero_as_utc and hours == 0 and minutes == 0:
        return tz.UTC
    else:
        if minutes > 59:
            raise ValueError('Invalid minutes in time zone offset')

        if hours > 23:
            raise ValueError('Invalid hours in time zone offset')

        return tz.tzoffset(None, mult * (hours * 60 + minutes) * 60)

def load_data(fobj):
    try:
        return _load_data(fobj)
    except struct.error as e:
        # struct.unpack fails when a read comes up short
        raise ValueError("Invalid TZif file: unexpected end of file") from e

def _parse_rfc(self, s):
    lines = s.splitlines()
    if not lines:
        raise ValueError("empty string")

    # Unfold
    i = 0
    while i < len(lines):
        line = lines[i].rstrip()
        if not line:
            del lines[i]
        elif i > 0 and line[0] == " ":
            lines[i-1] += line[1:]
            del lines[i]
        else:
            i += 1

    tzid = None
    comps = []
    invtz = False
    comptype = None
    for line in lines:
        if not line:
            continue
        name, value = line.split(':', 1)
        parms = name.split(';')
        if not parms:
            raise ValueError("empty property name")
        name = parms[0].upper()
        parms = parms[1:]
        if invtz:
            if name == "BEGIN":
                if value in ("STANDARD", "DAYLIGHT"):
                    # Process component
                    pass
                else:
                    raise ValueError("unknown component: "+value)
                comptype = value
                founddtstart = False
                tzoffsetfrom = None
                tzoffsetto = None
                rrulelines = []
                tzname = None
            elif name == "END":
                if value == "VTIMEZONE":
                    if comptype:
                        raise ValueError("component not closed: "+comptype)
                    if not tzid:
                        raise ValueError("mandatory TZID not found")
                    if not comps:
                        raise ValueError(
                            "at least one component is needed")
                    # Process vtimezone
                    self._vtz[tzid] = _tzicalvtz(tzid, comps)
                    invtz = False
                elif value == comptype:
                    if not founddtstart:
                        raise ValueError("mandatory DTSTART not found")
                    if tzoffsetfrom is None:
                        raise ValueError(
                            "mandatory TZOFFSETFROM not found")
                    if tzoffsetto is None:
                        raise ValueError(
                            "mandatory TZOFFSETFROM not found")
                    # Process component
                    rr = None
                    if rrulelines:
                        rr = rrule.rrulestr("\n".join(rrulelines),
                                            compatible=True,
                                            ignoretz=True,
                                            cache=True)
                    comp = _tzicalvtzcomp(tzoffsetfrom, tzoffsetto,
                                          (comptype == "DAYLIGHT"),
                                          tzname, rr)
                    comps.append(comp)
                    comptype = None
                else:
                    raise ValueError("invalid component end: "+value)
            elif comptype:
                if name == "DTSTART":
                    # DTSTART in VTIMEZONE takes a subset of valid RRULE
                    # values under RFC 5545.
                    for parm in parms:
                        if parm != 'VALUE=DATE-TIME':
                            msg = ('Unsupported DTSTART param in ' +
                                   'VTIMEZONE: ' + parm)
                            raise ValueError(msg)
                    rrulelines.append(line)
                    founddtstart = True
                elif name in ("RRULE", "RDATE", "EXRULE", "EXDATE"):
                    rrulelines.append(line)
                elif name == "TZOFFSETFROM":
                    if parms:
                        raise ValueError(
                            "unsupported %s parm: %s " % (name, parms[0]))
                    tzoffsetfrom = self._parse_offset(value)
                elif name == "TZOFFSETTO":
                    if parms:
                        raise ValueError(
                            "unsupported TZOFFSETTO parm: "+parms[0])
                    tzoffsetto = self._parse_offset(value)
                elif name == "TZNAME":
                    if parms:
                        raise ValueError(
                            "unsupported TZNAME parm: "+parms[0])
                    tzname = value
                elif name == "COMMENT":
                    pass
                else:
                    raise ValueError("unsupported property: "+name)
            else:
                if name == "TZID":
                    if parms:
                        raise ValueError(
                            "unsupported TZID parm: "+parms[0])
                    tzid = value
                elif name in ("TZURL", "LAST-MODIFIED", "COMMENT"):
                    pass
                else:
                    raise ValueError("unsupported property: "+name)
        elif name == "BEGIN" and value == "VTIMEZONE":
            tzid = None
            comps = []
            invtz = True

def __init__(self, fileobj, filename=None, key=None):
    super().__init__()

    file_opened_here = False
    if isinstance(fileobj, str):
        self._filename = fileobj
        fileobj = open(fileobj, "rb")
        file_opened_here = True
    elif filename is not None:
        self._filename = filename
    elif hasattr(fileobj, "name"):
        self._filename = fileobj.name
    elif key is not None:
        self._filename = key
    else:
        self._filename = repr(fileobj)

    if fileobj is not None:
        if not file_opened_here:
            fileobj = contextlib.nullcontext(fileobj)

        with fileobj as file_stream:
            self._load_file(file_stream)

    self._key = key

def from_file(cls, stream):
    # The header starts with a 4-byte "magic" value
    if stream.read(4) != b"TZif":
        raise ValueError("Invalid TZif file: magic not found")

    _version = stream.read(1)
    if _version == b"\x00":
        version = 1
    else:
        version = int(_version)
    stream.read(15)

    args = (version,)

    # Slots are defined in the order that the bytes are arranged
    args = args + struct.unpack(">6l", stream.read(24))

    return cls(*args)

def _eager_load_tzdata(self):
    try:
        import tzdata
    except ImportError as e:
        raise ImportError(
            "The tzdata module is required to use ZoneInfoFile; either add a dependency on tzdata or migrate away from dateutil.zoneinfo."
        ) from e

    zone_dict = {}

    for key in _tzdata_impl._load_tzdata_keys():
        with _tzdata_impl._load_tzdata(key) as f:
            zone_dict[key] = tzfile(f, key=key)

    self.zones = zone_dict
    self.metadata = {
        "metadata_version": "3.0",
        "tzversion": tzdata.IANA_VERSION,
    }

def _parse_rfc_rrule(self, line,
                     dtstart=None,
                     cache=False,
                     ignoretz=False,
                     tzinfos=None):
    if line.find(':') != -1:
        name, value = line.split(':')
        if name != "RRULE":
            raise ValueError("unknown parameter name")
    else:
        value = line
    rrkwargs = {}
    for pair in value.split(';'):
        name, value = pair.split('=')
        name = name.upper()
        value = value.upper()
        try:
            getattr(self, "_handle_"+name)(rrkwargs, name, value,
                                           ignoretz=ignoretz,
                                           tzinfos=tzinfos)
        except AttributeError:
            raise ValueError("unknown parameter '%s'" % name)
        except (KeyError, ValueError):
            raise ValueError("invalid '%s': %s" % (name, value))
    return rrule(dtstart=dtstart, cache=cache, **rrkwargs)

def _parse_tz_str(tz_str):
    # The tz string has the format:
    #
    # std[offset[dst[offset],start[/time],end[/time]]]
    #
    # std and dst must be 3 or more characters long and must not contain
    # a leading colon, embedded digits, commas, nor a plus or minus signs;
    # The spaces between "std" and "offset" are only for display and are
    # not actually present in the string.
    #
    # The format of the offset is ``[+|-]hh[:mm[:ss]]``

    offset_str, *start_end_str = tz_str.split(",", 1)

    parser_re = (
        r"(?P<std>[a-zA-Z]+|<[a-zA-Z0-9+-]+>)"
        r"(?:"
        r"(?P<stdoff>[+-]?\d{1,3}(?::\d{2}(?::\d{2})?)?)"
        r"(?:"
        r"(?P<dst>[a-zA-Z]+|<[a-zA-Z0-9+-]+>)"
        r"(?P<dstoff>[+-]?\d{1,3}(?::\d{2}(?::\d{2})?)?)?"
        r")?"  # dst
        r")?"  # stdoff
    )

    m = re.fullmatch(parser_re, offset_str, re.ASCII)

    if m is None:
        raise ValueError("%s is not a valid TZ string" % tz_str)

    std_abbr = m.group("std")
    dst_abbr = m.group("dst")
    dst_offset = None

    std_abbr = std_abbr.strip("<>")

    if dst_abbr:
        dst_abbr = dst_abbr.strip("<>")

    std_offset = m.group("stdoff")
    if std_offset:
        try:
            std_offset = _parse_tz_delta(std_offset)
        except ValueError as e:
            raise ValueError("Invalid STD offset in %s" % tz_str)
    else:
        # The STD offset is required
        raise ValueError("Invalid STD offset in %s" % tz_str)

    if dst_abbr is not None:
        dst_offset = m.group("dstoff")
        if dst_offset:
            try:
                dst_offset = _parse_tz_delta(dst_offset)
            except ValueError as e:
                raise ValueError("Invalid DST offset in %s" % tz_str)
        else:
            dst_offset = std_offset + 3600

        if not start_end_str:
            raise ValueError("Missing transition rules: %s" % tz_str)

        start_end_strs = start_end_str[0].split(",", 1)
        try:
            start, end = (_parse_dst_start_end(x) for x in start_end_strs)
        except ValueError as e:
            raise ValueError("Invalid TZ string: %s" % tz_str)

        return _TZStr(std_abbr, std_offset, dst_abbr, dst_offset, start, end)
    elif start_end_str:
        raise ValueError("Transition rule present without DST: %s" % tz_str)
    else:
        # This is a static ttinfo, don't return _TZStr
        return _ttinfo(
            _load_timedelta(std_offset), _load_timedelta(0), std_abbr
        )

def _is_seekable(fobj):
    if not hasattr(fobj, "seek"):
        return False

    seekable = getattr(fobj, "seekable", None)
    # File-like objects need not implement seekable().
    if seekable is not None and not seekable():
        return False

    if not _SEEKABLE_PIPES_BUG:
        return True

    # For anything backed by a file descriptor, only trust regular files.
    try:
        fd = fobj.fileno()
    except (AttributeError, OSError, ValueError):
        # io.UnsupportedOperation (e.g. from BytesIO) is both of the latter
        return True

    try:
        return stat.S_ISREG(os.fstat(fd).st_mode)
    except OSError:
        return True

