                                              s.startswith('RRULE:'))):
        return self._parse_rfc_rrule(lines[0], cache=cache,
                                     dtstart=dtstart, ignoretz=ignoretz,
                                     tzinfos=tzinfos)
    else:
        rrulevals = []
        rdatevals = []
        exrulevals = []
        exdatevals = []
        for line in lines:
            if not line:
                continue
            if line.find(':') == -1:
                name = "RRULE"
                value = line
            else:
                name, value = line.split(':', 1)
            parms = name.split(';')
            if not parms:
                raise ValueError("empty property name")
            name = parms[0]
            parms = parms[1:]
            if name == "RRULE":
                for parm in parms:
                    if parm.startswith("X-"):
                        # Experimental random vendor features; safe to ignore
                        continue
                    raise ValueError("unsupported RRULE parm: " + parm)
                rrulevals.append(value)
            elif name == "RDATE":
                for parm in parms:
                    if parm != "VALUE=DATE-TIME":
                        raise ValueError("unsupported RDATE parm: "+parm)
                rdatevals.append(value)
            elif name == "EXRULE":
                for parm in parms:
                    raise ValueError("unsupported EXRULE parm: "+parm)
                exrulevals.append(value)
            elif name == "EXDATE":
                exdatevals.extend(
                    self._parse_date_value(value, parms,
                                           TZID_NAMES, ignoretz,
                                           tzids, tzinfos)
                )
            elif name == "DTSTART":
                dtvals = self._parse_date_value(value, parms, TZID_NAMES,
                                                ignoretz, tzids, tzinfos)
                if len(dtvals) != 1:
                    raise ValueError("Multiple DTSTART values specified:" +
                                     value)
                dtstart = dtvals[0]
            else:
                raise ValueError("unsupported property: "+name)
        if (forceset or len(rrulevals) > 1 or rdatevals
                or exrulevals or exdatevals):
            if not parser and (rdatevals or exdatevals):
                from dateutil import parser
            rset = rruleset(cache=cache)
            for value in rrulevals:
                rset.rrule(self._parse_rfc_rrule(value, dtstart=dtstart,
                                                 ignoretz=ignoretz,
                                                 tzinfos=tzinfos))
            for value in rdatevals:
                for datestr in value.split(','):
                    rset.rdate(parser.parse(datestr,
                                            ignoretz=ignoretz,
                                            tzinfos=tzinfos))
            for value in exrulevals:
                rset.exrule(self._parse_rfc_rrule(value, dtstart=dtstart,
                                                  ignoretz=ignoretz,
                                                  tzinfos=tzinfos))
            for value in exdatevals:
                rset.exdate(value)
            if compatible and dtstart:
                rset.rdate(dtstart)
            return rset
        else:
            return self._parse_rfc_rrule(rrulevals[0],
                                         dtstart=dtstart,
                                         cache=cache,
                                         ignoretz=ignoretz,
                                         tzinfos=tzinfos)

def __repr__(self):
    args = ", ".join("'%s'" % arg for arg in self.args)
    return "%s(%s)" % (self.__class__.__name__, args)

def nocache(name=None):
    """A non-cached version of gettz"""
    tz = None
    if not name:
        try:
            name = os.environ["TZ"]
        except KeyError:
            pass
    if name is None or name in ("", ":"):
        for filepath in TZFILES:
            if not os.path.isabs(filepath):
                filename = filepath
                for path in _tzpath.TZPATH:
                    filepath = os.path.join(path, filename)
                    if os.path.isfile(filepath):
                        break
                else:
                    continue
            if os.path.isfile(filepath):
                try:
                    tz = tzfile(filepath)
                    break
                except (OSError, ValueError):
                    pass
        else:
            tz = tzlocal()
    else:
        try:
            if name.startswith(":"):
                name = name[1:]
        except TypeError as e:
            if isinstance(name, bytes):
                new_msg = "gettz argument should be str, not bytes"
                raise TypeError(new_msg) from e
            else:
                raise

        # A NUL byte can never be part of a key or a path, and
        # depending on the platform and Python version it raises
        # ValueError from os.path, winreg or open(), so reject it
        # up front rather than catching it in every branch.
        if "\x00" in name:
            return None

        if os.path.isabs(name):
            if os.path.isfile(name):
                tz = tzfile(name)
            else:
                tz = None
        else:
            if _escapes_tzpath(name):
                _warn_tzpath_escape(name)

            for path in _tzpath.TZPATH:
                filepath = os.path.join(path, name)
                if not os.path.isfile(filepath):
                    filepath = filepath.replace(' ', '_')
                    if not os.path.isfile(filepath):
                        continue
                try:
                    tz = tzfile(filepath, key=name)
                    break
                except (OSError, ValueError):
                    # TODO: A file that exists but can't be read or
                    # isn't a valid TZif file is silently skipped,
                    # and the key is looked up in the next TZPATH
                    # entry and then in tzdata. Consider warning
                    # here, since this usually means the system time
                    # zone data is broken.
                    pass
            else:
                tz = None
                # As with the search path lookup above, also try
                # the name with spaces replaced by underscores.
                candidates = [name]
                if " " in name:
                    candidates.append(name.replace(" ", "_"))

                for candidate in candidates:
                    try:
                        with _tzdata_impl._load_tzdata(candidate) as f:
                            return tzfile(f, key=name)
                    except ValueError:
                        # TZFileNotFound is a ValueError, and so is
                        # the error raised for files in tzdata that
                        # are not TZif files (e.g. "zone.tab"),
                        # which are skipped just as on TZPATH.
                        pass

                if tzwin is not None:
                    try:
                        tz = tzwin(name)
                    except OSError:
                        tz = None

                if not tz:
                    for c in name:
                        # name is not a tzstr unless it has at least
                        # one offset. For short values of "name", an
                        # explicit for loop seems to be the fastest way
                        # To determine if a string contains a digit
                        if c in "0123456789":
                            try:
                                tz = tzstr(name)
                            except ValueError:
                                pass
                            break
                    else:
                        if name in ("GMT", "UTC"):
                            tz = UTC
                        elif name in time.tzname:
                            tz = tzlocal()
    return tz

def __repr__(self):
    l = []
    for attr in ["years", "months", "days", "leapdays",
                 "hours", "minutes", "seconds", "microseconds"]:
        value = getattr(self, attr)
        if value:
            l.append("{attr}={value:+g}".format(attr=attr, value=value))
    for attr in ["year", "month", "day", "weekday",
                 "hour", "minute", "second", "microsecond"]:
        value = getattr(self, attr)
        if value is not None:
            l.append("{attr}={value}".format(attr=attr, value=repr(value)))
    return "{classname}({attrs})".format(classname=self.__class__.__name__,
                                         attrs=", ".join(l))

def __truediv__(self, other):
    try:
        reciprocal = 1 / float(other)
    except TypeError:
        return NotImplemented

    return self.__mul__(reciprocal)

def __init__(self, stdabbr, stdoffset=None,
             dstabbr=None, dstoffset=None,
             start=None, end=None):

    global relativedelta
    from dateutil import relativedelta

    self._std_abbr = stdabbr
    self._dst_abbr = dstabbr

    try:
        stdoffset = stdoffset.total_seconds()
    except (TypeError, AttributeError):
        pass

    try:
        dstoffset = dstoffset.total_seconds()
    except (TypeError, AttributeError):
        pass

    if stdoffset is not None:
        self._std_offset = datetime.timedelta(seconds=stdoffset)
    else:
        self._std_offset = ZERO

    if dstoffset is not None:
        self._dst_offset = datetime.timedelta(seconds=dstoffset)
    elif dstabbr and stdoffset is not None:
        self._dst_offset = self._std_offset + datetime.timedelta(hours=+1)
    else:
        self._dst_offset = ZERO

    if dstabbr and start is None:
        self._start_delta = relativedelta.relativedelta(
            hours=+2, month=4, day=1, weekday=relativedelta.SU(+1))
    else:
        self._start_delta = start

    if dstabbr and end is None:
        self._end_delta = relativedelta.relativedelta(
            hours=+1, month=10, day=31, weekday=relativedelta.SU(-1))
    else:
        self._end_delta = end

    self._dst_base_offset_ = self._dst_offset - self._std_offset
    self.hasdst = bool(self._start_delta)

def _delta(self, x, isend=0):
    from dateutil import relativedelta
    kwargs = {}
    if x.month is not None:
        kwargs["month"] = x.month
        if x.weekday is not None:
            kwargs["weekday"] = relativedelta.weekday(x.weekday, x.week)
            if x.week > 0:
                kwargs["day"] = 1
            else:
                kwargs["day"] = 31
        elif x.day:
            kwargs["day"] = x.day
    elif x.yday is not None:
        kwargs["yearday"] = x.yday
    elif x.jyday is not None:
        kwargs["nlyearday"] = x.jyday
    if not kwargs:
        # Default is to start on first sunday of april, and end
        # on last sunday of october.
        if not isend:
            kwargs["month"] = 4
            kwargs["day"] = 1
            kwargs["weekday"] = relativedelta.SU(+1)
        else:
            kwargs["month"] = 10
            kwargs["day"] = 31
            kwargs["weekday"] = relativedelta.SU(-1)
    if x.time is not None:
        kwargs["seconds"] = x.time
    else:
        # Default is 2AM.
        kwargs["seconds"] = 7200
    if isend:
        # Convert to standard time, to follow the documented way
        # of working with the extra hour. See the documentation
        # of the tzinfo class.
        delta = self._dst_offset - self._std_offset
        kwargs["seconds"] -= delta.seconds + delta.days * 86400
    return relativedelta.relativedelta(**kwargs)

def _parse_tzstr(self, tzstr, zero_as_utc=True):
    if tzstr == b'Z' or tzstr == b'z':
        return tz.UTC

    if len(tzstr) not in {3, 5, 6}:
        raise ValueError('Time zone offset must be 1, 3, 5 or 6 characters')

    if tzstr[0:1] == b'-':
        mult = -1
    elif tzstr[0:1] == b'+':
        mult = 1
    else:
        raise ValueError('Time zone offset requires sign')

    hours = self._parse_digits(tzstr, 1, 2)
    if len(tzstr) == 3:
        minutes = 0
    else:
        pos = 4 if tzstr[3:4] == self._TIME_SEP else 3
        if len(tzstr) != pos + 2:
            raise ValueError("Invalid minutes in time zone offset")
        minutes = self._parse_digits(tzstr, pos, 2)

    if zero_as_utc and hours == 0 and minutes == 0:
        return tz.UTC
    else:
        if minutes > 59:
            raise ValueError('Invalid minutes in time zone offset')

        if hours > 23:
            raise ValueError('Invalid hours in time zone offset')

        return tz.tzoffset(None, mult * (hours * 60 + minutes) * 60)

def _parse_rfc(self, s):
    lines = s.splitlines()
    if not lines:
        raise ValueError("empty string")

    # Unfold
    i = 0
    while i < len(lines):
        line = lines[i].rstrip()
        if not line:
            del lines[i]
        elif i > 0 and line[0] == " ":
            lines[i-1] += line[1:]
            del lines[i]
        else:
            i += 1

    tzid = None
    comps = []
    invtz = False
    comptype = None
    for line in lines:
        if not line:
            continue
        name, value = line.split(':', 1)
        parms = name.split(';')
        if not parms:
            raise ValueError("empty property name")
        name = parms[0].upper()
        parms = parms[1:]
        if invtz:
            if name == "BEGIN":
                if value in ("STANDARD", "DAYLIGHT"):
                    # Process component
                    pass
                else:
                    raise ValueError("unknown component: "+value)
                comptype = value
                founddtstart = False
                tzoffsetfrom = None
                tzoffsetto = None
                rrulelines = []
                tzname = None
            elif name == "END":
                if value == "VTIMEZONE":
                    if comptype:
                        raise ValueError("component not closed: "+comptype)
                    if not tzid:
                        raise ValueError("mandatory TZID not found")
                    if not comps:
                        raise ValueError(
                            "at least one component is needed")
                    # Process vtimezone
                    self._vtz[tzid] = _tzicalvtz(tzid, comps)
                    invtz = False
                elif value == comptype:
                    if not founddtstart:
                        raise ValueError("mandatory DTSTART not found")
                    if tzoffsetfrom is None:
                        raise ValueError(
                            "mandatory TZOFFSETFROM not found")
                    if tzoffsetto is None:
                        raise ValueError(
                            "mandatory TZOFFSETFROM not found")
                    # Process component
                    rr = None
                    if rrulelines:
                        rr = rrule.rrulestr("\n".join(rrulelines),
                                            compatible=True,
                                            ignoretz=True,
                                            cache=True)
                    comp = _tzicalvtzcomp(tzoffsetfrom, tzoffsetto,
                                          (comptype == "DAYLIGHT"),
                                          tzname, rr)
                    comps.append(comp)
                    comptype = None
                else:
                    raise ValueError("invalid component end: "+value)
            elif comptype:
                if name == "DTSTART":
                    # DTSTART in VTIMEZONE takes a subset of valid RRULE
                    # values under RFC 5545.
                    for parm in parms:
                        if parm != 'VALUE=DATE-TIME':
                            msg = ('Unsupported DTSTART param in ' +
                                   'VTIMEZONE: ' + parm)
                            raise ValueError(msg)
                    rrulelines.append(line)
                    founddtstart = True
                elif name in ("RRULE", "RDATE", "EXRULE", "EXDATE"):
                    rrulelines.append(line)
                elif name == "TZOFFSETFROM":
                    if parms:
                        raise ValueError(
                            "unsupported %s parm: %s " % (name, parms[0]))
                    tzoffsetfrom = self._parse_offset(value)
                elif name == "TZOFFSETTO":
                    if parms:
                        raise ValueError(
                            "unsupported TZOFFSETTO parm: "+parms[0])
                    tzoffsetto = self._parse_offset(value)
                elif name == "TZNAME":
                    if parms:
                        raise ValueError(
                            "unsupported TZNAME parm: "+parms[0])
                    tzname = value
                elif name == "COMMENT":
                    pass
                else:
                    raise ValueError("unsupported property: "+name)
            else:
                if name == "TZID":
                    if parms:
                        raise ValueError(
                            "unsupported TZID parm: "+parms[0])
                    tzid = value
                elif name in ("TZURL", "LAST-MODIFIED", "COMMENT"):
                    pass
                else:
                    raise ValueError("unsupported property: "+name)
        elif name == "BEGIN" and value == "VTIMEZONE":
            tzid = None
            comps = []
            invtz = True

def _parse_rfc_rrule(self, line,
                     dtstart=None,
                     cache=False,
                     ignoretz=False,
                     tzinfos=None):
    if line.find(':') != -1:
        name, value = line.split(':')
        if name != "RRULE":
            raise ValueError("unknown parameter name")
    else:
        value = line
    rrkwargs = {}
    for pair in value.split(';'):
        name, value = pair.split('=')
        name = name.upper()
        value = value.upper()
        try:
            getattr(self, "_handle_"+name)(rrkwargs, name, value,
                                           ignoretz=ignoretz,
                                           tzinfos=tzinfos)
        except AttributeError:
            raise ValueError("unknown parameter '%s'" % name)
        except (KeyError, ValueError):
            raise ValueError("invalid '%s': %s" % (name, value))
    return rrule(dtstart=dtstart, cache=cache, **rrkwargs)

def _parse_isodate_common(self, dt_str):
    len_str = len(dt_str)
    components = [1, 1, 1]

    if len_str < 4:
        raise ValueError('ISO string too short')

    # Year
    components[0] = self._parse_digits(dt_str, 0, 4)
    pos = 4
    if pos >= len_str:
        return components, pos

    has_sep = dt_str[pos:pos + 1] == self._DATE_SEP
    if has_sep:
        pos += 1

    # Month
    if len_str - pos < 2:
        raise ValueError('Invalid common month')

    components[1] = self._parse_digits(dt_str, pos, 2)
    pos += 2

    if pos >= len_str:
        if has_sep:
            return components, pos
        else:
            raise ValueError('Invalid ISO format')

    if has_sep:
        if dt_str[pos:pos + 1] != self._DATE_SEP:
            raise ValueError('Invalid separator in ISO string')
        pos += 1

    # Day
    if len_str - pos < 2:
        raise ValueError('Invalid common day')
    components[2] = self._parse_digits(dt_str, pos, 2)
    return components, pos + 2

def _parse_isodate(self, dt_str):
    try:
        return self._parse_isodate_common(dt_str)
    except ValueError:
        return self._parse_isodate_uncommon(dt_str)

def func(self, str_in, *args, **kwargs):
    # If it's a stream, read the whole thing
    str_in = getattr(str_in, 'read', lambda: str_in)()

    # If it's unicode, turn it into bytes, since ISO-8601 only covers ASCII
    if isinstance(str_in, str):
        # ASCII is the same in UTF-8
        try:
            str_in = str_in.encode('ascii')
        except UnicodeEncodeError as e:
            msg = 'ISO-8601 strings should contain only ASCII characters'
            raise ValueError(msg) from e

    return f(self, str_in, *args, **kwargs)

def _parse_isotime(self, timestr):
    len_str = len(timestr)
    components = [0, 0, 0, 0, None]
    pos = 0
    comp = -1

    if len_str < 2:
        raise ValueError('ISO time too short')

    has_sep = False

    while pos < len_str and comp < 5:
        comp += 1

        if timestr[pos:pos + 1] in b'-+Zz':
            # Detect time zone boundary
            components[-1] = self._parse_tzstr(timestr[pos:])
            pos = len_str
            break

        if comp == 1 and timestr[pos:pos+1] == self._TIME_SEP:
            has_sep = True
            pos += 1
        elif comp == 2 and has_sep:
            if timestr[pos:pos+1] != self._TIME_SEP:
                raise ValueError('Inconsistent use of colon separator')
            pos += 1

        if comp < 3:
            # Hour, minute, second
            components[comp] = self._parse_digits(timestr, pos, 2)
            pos += 2

        if comp == 3:
            # Fraction of a second
            frac = self._FRACTION_REGEX.match(timestr[pos:])
            if not frac:
                continue

            us_str = frac.group(1)[:6]  # Truncate to microseconds
            components[comp] = int(us_str) * 10**(6 - len(us_str))
            pos += len(frac.group())

    if pos < len_str:
        raise ValueError('Unused components in ISO string')

    if components[0] == 24:
        # Standard supports 00:00 and 24:00 as representations of midnight
        if any(component != 0 for component in components[1:4]):
            raise ValueError('Hour may only be 24 at 24:00:00.000')

    return components

def _parse_digits(self, s, pos, n):
    """Parse exactly ``n`` ASCII digits starting at ``pos``."""
    digits = s[pos : pos + n]
    if len(digits) != n or not digits.isdigit():
        raise ValueError(
            "Expected {} digits, got {!r}".format(n, digits.decode("ascii"))
        )
    return int(digits)

def _parse_rfc(self, s,
               dtstart=None,
               cache=False,
               unfold=False,
               forceset=False,
               compatible=False,
               ignoretz=False,
               tzids=None,
               tzinfos=None):
    global parser
    if compatible:
        forceset = True
        unfold = True

    TZID_NAMES = dict(map(
        lambda x: (x.upper(), x),
        re.findall('TZID=(?P<name>[^:]+):', s)
    ))
    s = s.upper()
    if not s.strip():
        raise ValueError("empty string")
    if unfold:
        lines = s.splitlines()
        i = 0
        while i < len(lines):
            line = lines[i].rstrip()
            if not line:
                del lines[i]
            elif i > 0 and line[0] == " ":
                lines[i-1] += line[1:]
                del lines[i]
            else:
                i += 1
    else:
        lines = s.split()
    if (not forceset and len(lines) == 1 and (s.find(':') == -1 or
                                              s.startswith('RRULE:'))):
        return self._parse_rfc_rrule(lines[0], cache=cache,
                                     dtstart=dtstart, ignoretz=ignoretz,
                                     tzinfos=tzinfos)
    else:
        rrulevals = []
        rdatevals = []
        exrulevals = []
        exdatevals = []
        for line in lines:
            if not line:
                continue
            if line.find(':') == -1:
                name = "RRULE"
                value = line
            else:
                name, value = line.split(':', 1)
            parms = name.split(';')
            if not parms:
                raise ValueError("empty property name")
            name = parms[0]
            parms = parms[1:]
            if name == "RRULE":
                for parm in parms:
                    if parm.startswith("X-"):
                        # Experimental random vendor features; safe to ignore
                        continue
                    raise ValueError("unsupported RRULE parm: " + parm)
                rrulevals.append(value)
            elif name == "RDATE":
                for parm in parms:
                    if parm != "VALUE=DATE-TIME":
                        raise ValueError("unsupported RDATE parm: "+parm)
                rdatevals.append(value)
            elif name == "EXRULE":
                for parm in parms:
                    raise ValueError("unsupported EXRULE parm: "+parm)
                exrulevals.append(value)
            elif name == "EXDATE":
                exdatevals.extend(
                    self._parse_date_value(value, parms,
                                           TZID_NAMES, ignoretz,
                                           tzids, tzinfos)
                )
            elif name == "DTSTART":
                dtvals = self._parse_date_value(value, parms, TZID_NAMES,
                                                ignoretz, tzids, tzinfos)
                if len(dtvals) != 1:
                    raise ValueError("Multiple DTSTART values specified:" +
                                     value)
                dtstart = dtvals[0]
            else:
                raise ValueError("unsupported property: "+name)
        if (forceset or len(rrulevals) > 1 or rdatevals
                or exrulevals or exdatevals):
            if not parser and (rdatevals or exdatevals):
                from dateutil import parser
            rset = rruleset(cache=cache)
            for value in rrulevals:
                rset.rrule(self._parse_rfc_rrule(value, dtstart=dtstart,
                                                 ignoretz=ignoretz,
                                                 tzinfos=tzinfos))
            for value in rdatevals:
                for datestr in value.split(','):
                    rset.rdate(parser.parse(datestr,
                                            ignoretz=ignoretz,
                                            tzinfos=tzinfos))
            for value in exrulevals:
                rset.exrule(self._parse_rfc_rrule(value, dtstart=dtstart,
                                                  ignoretz=ignoretz,
                                                  tzinfos=tzinfos))
            for value in exdatevals:
                rset.exdate(value)
            if compatible and dtstart:
                rset.rdate(dtstart)
            return rset
        else:
            return self._parse_rfc_rrule(rrulevals[0],
                                         dtstart=dtstart,
                                         cache=cache,
                                         ignoretz=ignoretz,
                                         tzinfos=tzinfos)

def weekday(self, name):
    try:
        return self._weekdays[name.lower()]
    except KeyError:
        pass
    return None

