                if value == "VTIMEZONE":
                    if comptype:
                        raise ValueError("component not closed: "+comptype)
                    if not tzid:
                        raise ValueError("mandatory TZID not found")
                    if not comps:
                        raise ValueError(
                            "at least one component is needed")
                    # Process vtimezone
                    self._vtz[tzid] = _tzicalvtz(tzid, comps)
                    invtz = False
                elif value == comptype:
                    if not founddtstart:
                        raise ValueError("mandatory DTSTART not found")
                    if tzoffsetfrom is None:
                        raise ValueError(
                            "mandatory TZOFFSETFROM not found")
                    if tzoffsetto is None:
                        raise ValueError(
                            "mandatory TZOFFSETFROM not found")
                    # Process component
                    rr = None
                    if rrulelines:
                        rr = rrule.rrulestr("\n".join(rrulelines),
                                            compatible=True,
                                            ignoretz=True,
                                            cache=True)
                    comp = _tzicalvtzcomp(tzoffsetfrom, tzoffsetto,
                                          (comptype == "DAYLIGHT"),
                                          tzname, rr)
                    comps.append(comp)
                    comptype = None
                else:
                    raise ValueError("invalid component end: "+value)
            elif comptype:
                if name == "DTSTART":
                    # DTSTART in VTIMEZONE takes a subset of valid RRULE
                    # values under RFC 5545.
                    for parm in parms:
                        if parm != 'VALUE=DATE-TIME':
                            msg = ('Unsupported DTSTART param in ' +
                                   'VTIMEZONE: ' + parm)
                            raise ValueError(msg)
                    rrulelines.append(line)
                    founddtstart = True
                elif name in ("RRULE", "RDATE", "EXRULE", "EXDATE"):
                    rrulelines.append(line)
                elif name == "TZOFFSETFROM":
                    if parms:
                        raise ValueError(
                            "unsupported %s parm: %s " % (name, parms[0]))
                    tzoffsetfrom = self._parse_offset(value)
                elif name == "TZOFFSETTO":
                    if parms:
                        raise ValueError(
                            "unsupported TZOFFSETTO parm: "+parms[0])
                    tzoffsetto = self._parse_offset(value)
                elif name == "TZNAME":
                    if parms:
                        raise ValueError(
                            "unsupported TZNAME parm: "+parms[0])
                    tzname = value
                elif name == "COMMENT":
                    pass
                else:
                    raise ValueError("unsupported property: "+name)
            else:
                if name == "TZID":
                    if parms:
                        raise ValueError(
                            "unsupported TZID parm: "+parms[0])
                    tzid = value
                elif name in ("TZURL", "LAST-MODIFIED", "COMMENT"):
                    pass
                else:
                    raise ValueError("unsupported property: "+name)
        elif name == "BEGIN" and value == "VTIMEZONE":
            tzid = None
            comps = []
            invtz = True

def __eq__(self, other):
    try:
        if self.weekday != other.weekday or self.n != other.n:
            return False
    except AttributeError:
        return False
    return True

def __repr__(self):
    s = ("MO", "TU", "WE", "TH", "FR", "SA", "SU")[self.weekday]
    if not self.n:
        return s
    else:
        return "%s(%+d)" % (s, self.n)

def _parse_tzstr(self, tzstr, zero_as_utc=True):
    if tzstr == b'Z' or tzstr == b'z':
        return tz.UTC

    if len(tzstr) not in {3, 5, 6}:
        raise ValueError('Time zone offset must be 1, 3, 5 or 6 characters')

    if tzstr[0:1] == b'-':
        mult = -1
    elif tzstr[0:1] == b'+':
        mult = 1
    else:
        raise ValueError('Time zone offset requires sign')

    hours = self._parse_digits(tzstr, 1, 2)
    if len(tzstr) == 3:
        minutes = 0
    else:
        pos = 4 if tzstr[3:4] == self._TIME_SEP else 3
        if len(tzstr) != pos + 2:
            raise ValueError("Invalid minutes in time zone offset")
        minutes = self._parse_digits(tzstr, pos, 2)

    if zero_as_utc and hours == 0 and minutes == 0:
        return tz.UTC
    else:
        if minutes > 59:
            raise ValueError('Invalid minutes in time zone offset')

        if hours > 23:
            raise ValueError('Invalid hours in time zone offset')

        return tz.tzoffset(None, mult * (hours * 60 + minutes) * 60)

def _parse_tz_str(tz_str):
    # The tz string has the format:
    #
    # std[offset[dst[offset],start[/time],end[/time]]]
    #
    # std and dst must be 3 or more characters long and must not contain
    # a leading colon, embedded digits, commas, nor a plus or minus signs;
    # The spaces between "std" and "offset" are only for display and are
    # not actually present in the string.
    #
    # The format of the offset is ``[+|-]hh[:mm[:ss]]``

    offset_str, *start_end_str = tz_str.split(",", 1)

    parser_re = (
        r"(?P<std>[a-zA-Z]+|<[a-zA-Z0-9+-]+>)"
        r"(?:"
        r"(?P<stdoff>[+-]?\d{1,3}(?::\d{2}(?::\d{2})?)?)"
        r"(?:"
        r"(?P<dst>[a-zA-Z]+|<[a-zA-Z0-9+-]+>)"
        r"(?P<dstoff>[+-]?\d{1,3}(?::\d{2}(?::\d{2})?)?)?"
        r")?"  # dst
        r")?"  # stdoff
    )

    m = re.fullmatch(parser_re, offset_str, re.ASCII)

    if m is None:
        raise ValueError("%s is not a valid TZ string" % tz_str)

    std_abbr = m.group("std")
    dst_abbr = m.group("dst")
    dst_offset = None

    std_abbr = std_abbr.strip("<>")

    if dst_abbr:
        dst_abbr = dst_abbr.strip("<>")

    std_offset = m.group("stdoff")
    if std_offset:
        try:
            std_offset = _parse_tz_delta(std_offset)
        except ValueError as e:
            raise ValueError("Invalid STD offset in %s" % tz_str)
    else:
        # The STD offset is required
        raise ValueError("Invalid STD offset in %s" % tz_str)

    if dst_abbr is not None:
        dst_offset = m.group("dstoff")
        if dst_offset:
            try:
                dst_offset = _parse_tz_delta(dst_offset)
            except ValueError as e:
                raise ValueError("Invalid DST offset in %s" % tz_str)
        else:
            dst_offset = std_offset + 3600

        if not start_end_str:
            raise ValueError("Missing transition rules: %s" % tz_str)

        start_end_strs = start_end_str[0].split(",", 1)
        try:
            start, end = (_parse_dst_start_end(x) for x in start_end_strs)
        except ValueError as e:
            raise ValueError("Invalid TZ string: %s" % tz_str)

        return _TZStr(std_abbr, std_offset, dst_abbr, dst_offset, start, end)
    elif start_end_str:
        raise ValueError("Transition rule present without DST: %s" % tz_str)
    else:
        # This is a static ttinfo, don't return _TZStr
        return _ttinfo(
            _load_timedelta(std_offset), _load_timedelta(0), std_abbr
        )

def _handle_BYWEEKDAY(self, rrkwargs, name, value, **kwargs):
    """
    Two ways to specify this: +1MO or MO(+1)
    """
    l = []
    for wday in value.split(','):
        if '(' in wday:
            # If it's of the form TH(+1), etc.
            splt = wday.split('(')
            w = splt[0]
            n = int(splt[1][:-1])
        elif len(wday):
            # If it's of the form +1MO
            for i in range(len(wday)):
                if wday[i] not in '+-0123456789':
                    break
            n = wday[:i] or None
            w = wday[i:]
            if n:
                n = int(n)
        else:
            raise ValueError("Invalid (empty) BYDAY specification.")

        l.append(weekdays[self._weekday_map[w]](n))
    rrkwargs["byweekday"] = l

def _parse_rfc_rrule(self, line,
                     dtstart=None,
                     cache=False,
                     ignoretz=False,
                     tzinfos=None):
    if line.find(':') != -1:
        name, value = line.split(':')
        if name != "RRULE":
            raise ValueError("unknown parameter name")
    else:
        value = line
    rrkwargs = {}
    for pair in value.split(';'):
        name, value = pair.split('=')
        name = name.upper()
        value = value.upper()
        try:
            getattr(self, "_handle_"+name)(rrkwargs, name, value,
                                           ignoretz=ignoretz,
                                           tzinfos=tzinfos)
        except AttributeError:
            raise ValueError("unknown parameter '%s'" % name)
        except (KeyError, ValueError):
            raise ValueError("invalid '%s': %s" % (name, value))
    return rrule(dtstart=dtstart, cache=cache, **rrkwargs)

def _parse_rfc(self, s,
               dtstart=None,
               cache=False,
               unfold=False,
               forceset=False,
               compatible=False,
               ignoretz=False,
               tzids=None,
               tzinfos=None):
    global parser
    if compatible:
        forceset = True
        unfold = True

    TZID_NAMES = dict(map(
        lambda x: (x.upper(), x),
        re.findall('TZID=(?P<name>[^:]+):', s)
    ))
    s = s.upper()
    if not s.strip():
        raise ValueError("empty string")
    if unfold:
        lines = s.splitlines()
        i = 0
        while i < len(lines):
            line = lines[i].rstrip()
            if not line:
                del lines[i]
            elif i > 0 and line[0] == " ":
                lines[i-1] += line[1:]
                del lines[i]
            else:
                i += 1
    else:
        lines = s.split()
    if (not forceset and len(lines) == 1 and (s.find(':') == -1 or
                                              s.startswith('RRULE:'))):
        return self._parse_rfc_rrule(lines[0], cache=cache,
                                     dtstart=dtstart, ignoretz=ignoretz,
                                     tzinfos=tzinfos)
    else:
        rrulevals = []
        rdatevals = []
        exrulevals = []
        exdatevals = []
        for line in lines:
            if not line:
                continue
            if line.find(':') == -1:
                name = "RRULE"
                value = line
            else:
                name, value = line.split(':', 1)
            parms = name.split(';')
            if not parms:
                raise ValueError("empty property name")
            name = parms[0]
            parms = parms[1:]
            if name == "RRULE":
                for parm in parms:
                    if parm.startswith("X-"):
                        # Experimental random vendor features; safe to ignore
                        continue
                    raise ValueError("unsupported RRULE parm: " + parm)
                rrulevals.append(value)
            elif name == "RDATE":
                for parm in parms:
                    if parm != "VALUE=DATE-TIME":
                        raise ValueError("unsupported RDATE parm: "+parm)
                rdatevals.append(value)
            elif name == "EXRULE":
                for parm in parms:
                    raise ValueError("unsupported EXRULE parm: "+parm)
                exrulevals.append(value)
            elif name == "EXDATE":
                exdatevals.extend(
                    self._parse_date_value(value, parms,
                                           TZID_NAMES, ignoretz,
                                           tzids, tzinfos)
                )
            elif name == "DTSTART":
                dtvals = self._parse_date_value(value, parms, TZID_NAMES,
                                                ignoretz, tzids, tzinfos)
                if len(dtvals) != 1:
                    raise ValueError("Multiple DTSTART values specified:" +
                                     value)
                dtstart = dtvals[0]
            else:
                raise ValueError("unsupported property: "+name)
        if (forceset or len(rrulevals) > 1 or rdatevals
                or exrulevals or exdatevals):
            if not parser and (rdatevals or exdatevals):
                from dateutil import parser
            rset = rruleset(cache=cache)
            for value in rrulevals:
                rset.rrule(self._parse_rfc_rrule(value, dtstart=dtstart,
                                                 ignoretz=ignoretz,
                                                 tzinfos=tzinfos))
            for value in rdatevals:
                for datestr in value.split(','):
                    rset.rdate(parser.parse(datestr,
                                            ignoretz=ignoretz,
                                            tzinfos=tzinfos))
            for value in exrulevals:
                rset.exrule(self._parse_rfc_rrule(value, dtstart=dtstart,
                                                  ignoretz=ignoretz,
                                                  tzinfos=tzinfos))
            for value in exdatevals:
                rset.exdate(value)
            if compatible and dtstart:
                rset.rdate(dtstart)
            return rset
        else:
            return self._parse_rfc_rrule(rrulevals[0],
                                         dtstart=dtstart,
                                         cache=cache,
                                         ignoretz=ignoretz,
                                         tzinfos=tzinfos)

def __init__(self, fileobj):
    global rrule
    from dateutil import rrule

    if isinstance(fileobj, str):
        self._s = fileobj
        # ical should be encoded in UTF-8 with CRLF
        fileobj = open(fileobj, 'r')
    else:
        self._s = getattr(fileobj, 'name', repr(fileobj))
        fileobj = contextlib.nullcontext(fileobj)

    self._vtz = {}

    with fileobj as fobj:
        self._parse_rfc(fobj.read())

def _parse_rfc(self, s):
    lines = s.splitlines()
    if not lines:
        raise ValueError("empty string")

    # Unfold
    i = 0
    while i < len(lines):
        line = lines[i].rstrip()
        if not line:
            del lines[i]
        elif i > 0 and line[0] == " ":
            lines[i-1] += line[1:]
            del lines[i]
        else:
            i += 1

    tzid = None
    comps = []
    invtz = False
    comptype = None
    for line in lines:
        if not line:
            continue
        name, value = line.split(':', 1)
        parms = name.split(';')
        if not parms:
            raise ValueError("empty property name")
        name = parms[0].upper()
        parms = parms[1:]
        if invtz:
            if name == "BEGIN":
                if value in ("STANDARD", "DAYLIGHT"):
                    # Process component
                    pass
                else:
                    raise ValueError("unknown component: "+value)
                comptype = value
                founddtstart = False
                tzoffsetfrom = None
                tzoffsetto = None
                rrulelines = []
                tzname = None
            elif name == "END":
                if value == "VTIMEZONE":
                    if comptype:
                        raise ValueError("component not closed: "+comptype)
                    if not tzid:
                        raise ValueError("mandatory TZID not found")
                    if not comps:
                        raise ValueError(
                            "at least one component is needed")
                    # Process vtimezone
                    self._vtz[tzid] = _tzicalvtz(tzid, comps)
                    invtz = False
                elif value == comptype:
                    if not founddtstart:
                        raise ValueError("mandatory DTSTART not found")
                    if tzoffsetfrom is None:
                        raise ValueError(
                            "mandatory TZOFFSETFROM not found")
                    if tzoffsetto is None:
                        raise ValueError(
                            "mandatory TZOFFSETFROM not found")
                    # Process component
                    rr = None
                    if rrulelines:
                        rr = rrule.rrulestr("\n".join(rrulelines),
                                            compatible=True,
                                            ignoretz=True,
                                            cache=True)
                    comp = _tzicalvtzcomp(tzoffsetfrom, tzoffsetto,
                                          (comptype == "DAYLIGHT"),
                                          tzname, rr)
                    comps.append(comp)
                    comptype = None
                else:
                    raise ValueError("invalid component end: "+value)
            elif comptype:
                if name == "DTSTART":
                    # DTSTART in VTIMEZONE takes a subset of valid RRULE
                    # values under RFC 5545.
                    for parm in parms:
                        if parm != 'VALUE=DATE-TIME':
                            msg = ('Unsupported DTSTART param in ' +
                                   'VTIMEZONE: ' + parm)
                            raise ValueError(msg)
                    rrulelines.append(line)
                    founddtstart = True
                elif name in ("RRULE", "RDATE", "EXRULE", "EXDATE"):
                    rrulelines.append(line)
                elif name == "TZOFFSETFROM":
                    if parms:
                        raise ValueError(
                            "unsupported %s parm: %s " % (name, parms[0]))
                    tzoffsetfrom = self._parse_offset(value)
                elif name == "TZOFFSETTO":
                    if parms:
                        raise ValueError(
                            "unsupported TZOFFSETTO parm: "+parms[0])
                    tzoffsetto = self._parse_offset(value)
                elif name == "TZNAME":
                    if parms:
                        raise ValueError(
                            "unsupported TZNAME parm: "+parms[0])
                    tzname = value
                elif name == "COMMENT":
                    pass
                else:
                    raise ValueError("unsupported property: "+name)
            else:
                if name == "TZID":
                    if parms:
                        raise ValueError(
                            "unsupported TZID parm: "+parms[0])
                    tzid = value
                elif name in ("TZURL", "LAST-MODIFIED", "COMMENT"):
                    pass
                else:
                    raise ValueError("unsupported property: "+name)
        elif name == "BEGIN" and value == "VTIMEZONE":
            tzid = None
            comps = []
            invtz = True

def __init__(self, rrule):
    for attr in self.__slots__:
        setattr(self, attr, None)
    self.rrule = rrule

def append(self, val, label=None):
    if hasattr(val, '__len__'):
        if val.isdigit() and len(val) > 2:
            self.century_specified = True
            if label not in [None, 'Y']:  # pragma: no cover
                raise ValueError(label)
            label = 'Y'
    elif val > 100:
        self.century_specified = True
        if label not in [None, 'Y']:  # pragma: no cover
            raise ValueError(label)
        label = 'Y'

    super().append(int(val))

    if label == 'M':
        if self.has_month:
            raise ValueError('Month is already set')
        self.mstridx = len(self) - 1
    elif label == 'D':
        if self.has_day:
            raise ValueError('Day is already set')
        self.dstridx = len(self) - 1
    elif label == 'Y':
        if self.has_year:
            raise ValueError('Year is already set')
        self.ystridx = len(self) - 1

def _handle_UNTIL(self, rrkwargs, name, value, **kwargs):
    global parser
    if not parser:
        from dateutil import parser
    try:
        rrkwargs["until"] = parser.parse(value,
                                         ignoretz=kwargs.get("ignoretz"),
                                         tzinfos=kwargs.get("tzinfos"))
    except ValueError:
        raise ValueError("invalid until date")

def __init__(self, freq, dtstart=None,
             interval=1, wkst=None, count=None, until=None, bysetpos=None,
             bymonth=None, bymonthday=None, byyearday=None, byeaster=None,
             byweekno=None, byweekday=None,
             byhour=None, byminute=None, bysecond=None,
             cache=False):
    super().__init__(cache)
    global easter
    if not dtstart:
        if until and until.tzinfo:
            dtstart = datetime.datetime.now(tz=until.tzinfo).replace(microsecond=0)
        else:
            dtstart = datetime.datetime.now().replace(microsecond=0)
    elif not isinstance(dtstart, datetime.datetime):
        dtstart = datetime.datetime.fromordinal(dtstart.toordinal())
    else:
        dtstart = dtstart.replace(microsecond=0)
    self._dtstart = dtstart
    self._tzinfo = dtstart.tzinfo
    self._freq = freq
    self._interval = interval
    self._count = count

    # Cache the original byxxx rules, if they are provided, as the _byxxx
    # attributes do not necessarily map to the inputs, and this can be
    # a problem in generating the strings. Only store things if they've
    # been supplied (the string retrieval will just use .get())
    self._original_rule = {}

    if until and not isinstance(until, datetime.datetime):
        until = datetime.datetime.fromordinal(until.toordinal())
    self._until = until

    if self._dtstart and self._until:
        if (self._dtstart.tzinfo is not None) != (self._until.tzinfo is not None):
            # According to RFC5545 Section 3.3.10:
            # https://tools.ietf.org/html/rfc5545#section-3.3.10
            #
            # > If the "DTSTART" property is specified as a date with UTC
            # > time or a date with local time and time zone reference,
            # > then the UNTIL rule part MUST be specified as a date with
            # > UTC time.
            raise ValueError(
                'RRULE UNTIL values must be specified in UTC when DTSTART '
                'is timezone-aware'
            )

    if count is not None and until:
        warn("Using both 'count' and 'until' is inconsistent with RFC 5545"
             " and has been deprecated in dateutil. Future versions will "
             "raise an error.", DeprecationWarning)

    if wkst is None:
        self._wkst = calendar.firstweekday()
    elif isinstance(wkst, int):
        self._wkst = wkst
    else:
        self._wkst = wkst.weekday

    if bysetpos is None:
        self._bysetpos = None
    elif isinstance(bysetpos, int):
        if bysetpos == 0 or not (-366 <= bysetpos <= 366):
            raise ValueError("bysetpos must be between 1 and 366, "
                             "or between -366 and -1")
        self._bysetpos = (bysetpos,)
    else:
        self._bysetpos = tuple(bysetpos)
        for pos in self._bysetpos:
            if pos == 0 or not (-366 <= pos <= 366):
                raise ValueError("bysetpos must be between 1 and 366, "
                                 "or between -366 and -1")

    if self._bysetpos:
        self._original_rule['bysetpos'] = self._bysetpos

    if (byweekno is None and byyearday is None and bymonthday is None and
            byweekday is None and byeaster is None):
        if freq == YEARLY:
            if bymonth is None:
                bymonth = dtstart.month
                self._original_rule['bymonth'] = None
            bymonthday = dtstart.day
            self._original_rule['bymonthday'] = None
        elif freq == MONTHLY:
            bymonthday = dtstart.day
            self._original_rule['bymonthday'] = None
        elif freq == WEEKLY:
            byweekday = dtstart.weekday()
            self._original_rule['byweekday'] = None

    # bymonth
    if bymonth is None:
        self._bymonth = None
    else:
        if isinstance(bymonth, int):
            bymonth = (bymonth,)

        self._bymonth = tuple(sorted(set(bymonth)))

        if 'bymonth' not in self._original_rule:
            self._original_rule['bymonth'] = self._bymonth

    # byyearday
    if byyearday is None:
        self._byyearday = None
    else:
        if isinstance(byyearday, int):
            byyearday = (byyearday,)

        self._byyearday = tuple(sorted(set(byyearday)))
        self._original_rule['byyearday'] = self._byyearday

    # byeaster
    if byeaster is not None:
        if not easter:
            from dateutil import easter
        if isinstance(byeaster, int):
            self._byeaster = (byeaster,)
        else:
            self._byeaster = tuple(sorted(byeaster))

        self._original_rule['byeaster'] = self._byeaster
    else:
        self._byeaster = None

    # bymonthday
    if bymonthday is None:
        self._bymonthday = ()
        self._bynmonthday = ()
    else:
        if isinstance(bymonthday, int):
            bymonthday = (bymonthday,)

        bymonthday = set(bymonthday)            # Ensure it's unique

        self._bymonthday = tuple(sorted(x for x in bymonthday if x > 0))
        self._bynmonthday = tuple(sorted(x for x in bymonthday if x < 0))

        # Storing positive numbers first, then negative numbers
        if 'bymonthday' not in self._original_rule:
            self._original_rule['bymonthday'] = tuple(
                itertools.chain(self._bymonthday, self._bynmonthday))

    # byweekno
    if byweekno is None:
        self._byweekno = None
    else:
        if isinstance(byweekno, int):
            byweekno = (byweekno,)

        self._byweekno = tuple(sorted(set(byweekno)))

        self._original_rule['byweekno'] = self._byweekno

    # byweekday / bynweekday
    if byweekday is None:
        self._byweekday = None
        self._bynweekday = None
    else:
        # If it's one of the valid non-sequence types, convert to a
        # single-element sequence before the iterator that builds the
        # byweekday set.
        if isinstance(byweekday, int) or hasattr(byweekday, "n"):
            byweekday = (byweekday,)

        self._byweekday = set()
        self._bynweekday = set()
        for wday in byweekday:
            if isinstance(wday, int):
                self._byweekday.add(wday)
            elif not wday.n or freq > MONTHLY:
                self._byweekday.add(wday.weekday)
            else:
                self._bynweekday.add((wday.weekday, wday.n))

        if not self._byweekday:
            self._byweekday = None
        elif not self._bynweekday:
            self._bynweekday = None

        if self._byweekday is not None:
            self._byweekday = tuple(sorted(self._byweekday))
            orig_byweekday = [weekday(x) for x in self._byweekday]
        else:
            orig_byweekday = ()

        if self._bynweekday is not None:
            self._bynweekday = tuple(sorted(self._bynweekday))
            orig_bynweekday = [weekday(*x) for x in self._bynweekday]
        else:
            orig_bynweekday = ()

        if 'byweekday' not in self._original_rule:
            self._original_rule['byweekday'] = tuple(itertools.chain(
                orig_byweekday, orig_bynweekday))

    # byhour
    if byhour is None:
        if freq < HOURLY:
            self._byhour = {dtstart.hour}
        else:
            self._byhour = None
    else:
        if isinstance(byhour, int):
            byhour = (byhour,)

        if freq == HOURLY:
            self._byhour = self.__construct_byset(start=dtstart.hour,
                                                  byxxx=byhour,
                                                  base=24)
        else:
            self._byhour = set(byhour)

        self._byhour = tuple(sorted(self._byhour))
        self._original_rule['byhour'] = self._byhour

    # byminute
    if byminute is None:
        if freq < MINUTELY:
            self._byminute = {dtstart.minute}
        else:
            self._byminute = None
    else:
        if isinstance(byminute, int):
            byminute = (byminute,)

        if freq == MINUTELY:
            self._byminute = self.__construct_byset(start=dtstart.minute,
                                                    byxxx=byminute,
                                                    base=60)
        else:
            self._byminute = set(byminute)

        self._byminute = tuple(sorted(self._byminute))
        self._original_rule['byminute'] = self._byminute

    # bysecond
    if bysecond is None:
        if freq < SECONDLY:
            self._bysecond = ((dtstart.second,))
        else:
            self._bysecond = None
    else:
        if isinstance(bysecond, int):
            bysecond = (bysecond,)

        self._bysecond = set(bysecond)

        if freq == SECONDLY:
            self._bysecond = self.__construct_byset(start=dtstart.second,
                                                    byxxx=bysecond,
                                                    base=60)
        else:
            self._bysecond = set(bysecond)

        self._bysecond = tuple(sorted(self._bysecond))
        self._original_rule['bysecond'] = self._bysecond

    if self._freq >= HOURLY:
        self._timeset = None
    else:
        self._timeset = []
        for hour in self._byhour:
            for minute in self._byminute:
                for second in self._bysecond:
                    self._timeset.append(
                        datetime.time(hour, minute, second,
                                      tzinfo=self._tzinfo))
        self._timeset.sort()
        self._timeset = tuple(self._timeset)

