        lines = s.splitlines()
        i = 0
        while i < len(lines):
            line = lines[i].rstrip()
            if not line:
                del lines[i]
            elif i > 0 and line[0] == " ":
                lines[i-1] += line[1:]
                del lines[i]
            else:
                i += 1
    else:
        lines = s.split()
    if (not forceset and len(lines) == 1 and (s.find(':') == -1 or
                                              s.startswith('RRULE:'))):
        return self._parse_rfc_rrule(lines[0], cache=cache,
                                     dtstart=dtstart, ignoretz=ignoretz,
                                     tzinfos=tzinfos)
    else:
        rrulevals = []
        rdatevals = []
        exrulevals = []
        exdatevals = []
        for line in lines:
            if not line:
                continue
            if line.find(':') == -1:
                name = "RRULE"
                value = line
            else:
                name, value = line.split(':', 1)
            parms = name.split(';')
            if not parms:
                raise ValueError("empty property name")
            name = parms[0]
            parms = parms[1:]
            if name == "RRULE":
                for parm in parms:
                    if parm.startswith("X-"):
                        # Experimental random vendor features; safe to ignore
                        continue
                    raise ValueError("unsupported RRULE parm: " + parm)
                rrulevals.append(value)
            elif name == "RDATE":
                for parm in parms:
                    if parm != "VALUE=DATE-TIME":
                        raise ValueError("unsupported RDATE parm: "+parm)
                rdatevals.append(value)
            elif name == "EXRULE":
                for parm in parms:
                    raise ValueError("unsupported EXRULE parm: "+parm)
                exrulevals.append(value)
            elif name == "EXDATE":
                exdatevals.extend(
                    self._parse_date_value(value, parms,
                                           TZID_NAMES, ignoretz,
                                           tzids, tzinfos)
                )
            elif name == "DTSTART":
