def __init__(self, instream):
    if isinstance(instream, (bytes, bytearray)):
        instream = instream.decode()

    if isinstance(instream, str):
        instream = StringIO(instream)
    elif getattr(instream, 'read', None) is None:
        raise TypeError('Parser must be a string or character stream, not '
                        '{itype}'.format(itype=instream.__class__.__name__))

    self.instream = instream
    self.charstack = []
    self.tokenstack = []
    self.eof = False

def _get_trans_info_near_new_year(self, ts, fold):
    # Answer the question in terms of UTC, where the transitions from the
    # adjacent years are taken into account: a local time is valid for
    # an offset if the rules give that offset at the corresponding UTC
    # time.
    valid = []
    for tti in (self.std, self.dst):
        utc_ts = ts - tti.utcoff.total_seconds()
        try:
            utc_year = (EPOCH + timedelta(seconds=utc_ts)).year
        except OverflowError:
            # Before year 1 or after year 9999
            utc_year = MINYEAR if utc_ts < 0 else MAXYEAR
        actual, _ = self._get_trans_info_fromutc_near_new_year(
            utc_ts, utc_year
        )
        if actual is tti:
            valid.append(tti)

    if len(valid) == 1:
        return valid[0]

    smaller, larger = sorted((self.std, self.dst), key=lambda t: t.utcoff)
    if valid:
        # Ambiguous: fold=0 is the first occurrence, with the larger offset
        return larger if fold == 0 else smaller
    else:
        # Imaginary: fold=0 uses the offset from before the transition
        return smaller if fold == 0 else larger

def _parse_rfc_rrule(self, line,
                     dtstart=None,
                     cache=False,
                     ignoretz=False,
                     tzinfos=None):
    if line.find(':') != -1:
        name, value = line.split(':')
        if name != "RRULE":
            raise ValueError("unknown parameter name")
    else:
        value = line
    rrkwargs = {}
    for pair in value.split(';'):
        name, value = pair.split('=')
        name = name.upper()
        value = value.upper()
        try:
            getattr(self, "_handle_"+name)(rrkwargs, name, value,
                                           ignoretz=ignoretz,
                                           tzinfos=tzinfos)
        except AttributeError:
            raise ValueError("unknown parameter '%s'" % name)
        except (KeyError, ValueError):
            raise ValueError("invalid '%s': %s" % (name, value))
    return rrule(dtstart=dtstart, cache=cache, **rrkwargs)

def _parse_tz_str(tz_str):
    # The tz string has the format:
    #
    # std[offset[dst[offset],start[/time],end[/time]]]
    #
    # std and dst must be 3 or more characters long and must not contain
    # a leading colon, embedded digits, commas, nor a plus or minus signs;
    # The spaces between "std" and "offset" are only for display and are
    # not actually present in the string.
    #
    # The format of the offset is ``[+|-]hh[:mm[:ss]]``

    offset_str, *start_end_str = tz_str.split(",", 1)

    parser_re = (
        r"(?P<std>[a-zA-Z]+|<[a-zA-Z0-9+-]+>)"
        r"(?:"
        r"(?P<stdoff>[+-]?\d{1,3}(?::\d{2}(?::\d{2})?)?)"
        r"(?:"
        r"(?P<dst>[a-zA-Z]+|<[a-zA-Z0-9+-]+>)"
        r"(?P<dstoff>[+-]?\d{1,3}(?::\d{2}(?::\d{2})?)?)?"
        r")?"  # dst
        r")?"  # stdoff
    )

    m = re.fullmatch(parser_re, offset_str, re.ASCII)

    if m is None:
        raise ValueError("%s is not a valid TZ string" % tz_str)

    std_abbr = m.group("std")
    dst_abbr = m.group("dst")
    dst_offset = None

    std_abbr = std_abbr.strip("<>")

    if dst_abbr:
        dst_abbr = dst_abbr.strip("<>")

    std_offset = m.group("stdoff")
    if std_offset:
        try:
            std_offset = _parse_tz_delta(std_offset)
        except ValueError as e:
            raise ValueError("Invalid STD offset in %s" % tz_str)
    else:
        # The STD offset is required
        raise ValueError("Invalid STD offset in %s" % tz_str)

    if dst_abbr is not None:
        dst_offset = m.group("dstoff")
        if dst_offset:
            try:
                dst_offset = _parse_tz_delta(dst_offset)
            except ValueError as e:
                raise ValueError("Invalid DST offset in %s" % tz_str)
        else:
            dst_offset = std_offset + 3600

        if not start_end_str:
            raise ValueError("Missing transition rules: %s" % tz_str)

        start_end_strs = start_end_str[0].split(",", 1)
        try:
            start, end = (_parse_dst_start_end(x) for x in start_end_strs)
        except ValueError as e:
            raise ValueError("Invalid TZ string: %s" % tz_str)

        return _TZStr(std_abbr, std_offset, dst_abbr, dst_offset, start, end)
    elif start_end_str:
        raise ValueError("Transition rule present without DST: %s" % tz_str)
    else:
        # This is a static ttinfo, don't return _TZStr
        return _ttinfo(
            _load_timedelta(std_offset), _load_timedelta(0), std_abbr
        )

def _get_trans_info(self, ts, year, fold):
    """Get the information about the current transition - tti"""
    if self._near_new_year(ts, year):
        return self._get_trans_info_near_new_year(ts, fold)

    start, end = self.transitions(year)

    # With fold = 0, the period (denominated in local time) with the
    # smaller offset starts at the end of the gap and ends at the end of
    # the fold; with fold = 1, it runs from the start of the gap to the
    # beginning of the fold.
    #
    # So in order to determine the DST boundaries we need to know both
    # the fold and whether DST is positive or negative (rare), and it
    # turns out that this boils down to fold XOR is_positive.
    if fold == (self.dst_diff >= 0):
        end -= self.dst_diff
    else:
        start += self.dst_diff

    if start < end:
        isdst = start <= ts < end
    else:
        isdst = not (end <= ts < start)

    return self.dst if isdst else self.std

def _eager_load_tzdata(self):
    try:
        import tzdata
    except ImportError as e:
        raise ImportError(
            "The tzdata module is required to use ZoneInfoFile; either add a dependency on tzdata or migrate away from dateutil.zoneinfo."
        ) from e

    zone_dict = {}

    for key in _tzdata_impl._load_tzdata_keys():
        with _tzdata_impl._load_tzdata(key) as f:
            zone_dict[key] = tzfile(f, key=key)

    self.zones = zone_dict
    self.metadata = {
        "metadata_version": "3.0",
        "tzversion": tzdata.IANA_VERSION,
    }

def _find_trans(self, dt, fold=None, timestamp=None):
    if dt is None:
        if self._fixed_offset:
            return self._tz_after
        else:
            return _NO_TTINFO

    if timestamp is None:
        ts = self._get_local_timestamp(dt)
    else:
        ts = timestamp

    if fold is None:
        fold = dt.fold

    lt = self._trans_local[fold]

    num_trans = len(lt)

    if num_trans and ts < lt[0]:
        return self._tti_before
    elif not num_trans or ts > lt[-1]:
        if isinstance(self._tz_after, _TZStr):
            tti = self._tz_after.get_trans_info(ts, dt.year, fold)

            # The TZ string only describes times after the last explicit
            # transition. If its answer for this local time is a different
            # offset from the last transition's, and corresponds to a time
            # before that transition (e.g. when the TZ string's own DST
            # period for that year ends after the transition), the offset
            # from the last explicit transition applies instead.
            last_tti = self._ttinfos[-1] if num_trans else None
            if (
                last_tti is not None
                and tti.utcoff != last_tti.utcoff
                and ts - tti.utcoff.total_seconds() < self._trans_utc[-1]
            ):
                return last_tti

            return tti
        else:
            return self._tz_after
    else:
        # idx is the transition that occurs after this timestamp, so we
        # subtract off 1 to get the current ttinfo
        idx = bisect.bisect_right(lt, ts) - 1
        assert idx >= 0
        return self._ttinfos[idx]

def _parse_rfc(self, s,
               dtstart=None,
               cache=False,
               unfold=False,
               forceset=False,
               compatible=False,
               ignoretz=False,
               tzids=None,
               tzinfos=None):
    global parser
    if compatible:
        forceset = True
        unfold = True

    TZID_NAMES = dict(map(
        lambda x: (x.upper(), x),
        re.findall('TZID=(?P<name>[^:]+):', s)
    ))
    s = s.upper()
    if not s.strip():
        raise ValueError("empty string")
    if unfold:
        lines = s.splitlines()
        i = 0
        while i < len(lines):
            line = lines[i].rstrip()
            if not line:
                del lines[i]
            elif i > 0 and line[0] == " ":
                lines[i-1] += line[1:]
                del lines[i]
            else:
                i += 1
    else:
        lines = s.split()
    if (not forceset and len(lines) == 1 and (s.find(':') == -1 or
                                              s.startswith('RRULE:'))):
        return self._parse_rfc_rrule(lines[0], cache=cache,
                                     dtstart=dtstart, ignoretz=ignoretz,
                                     tzinfos=tzinfos)
    else:
        rrulevals = []
        rdatevals = []
        exrulevals = []
        exdatevals = []
        for line in lines:
            if not line:
                continue
            if line.find(':') == -1:
                name = "RRULE"
                value = line
            else:
                name, value = line.split(':', 1)
            parms = name.split(';')
            if not parms:
                raise ValueError("empty property name")
            name = parms[0]
            parms = parms[1:]
            if name == "RRULE":
                for parm in parms:
                    if parm.startswith("X-"):
                        # Experimental random vendor features; safe to ignore
                        continue
                    raise ValueError("unsupported RRULE parm: " + parm)
                rrulevals.append(value)
            elif name == "RDATE":
                for parm in parms:
                    if parm != "VALUE=DATE-TIME":
                        raise ValueError("unsupported RDATE parm: "+parm)
                rdatevals.append(value)
            elif name == "EXRULE":
                for parm in parms:
                    raise ValueError("unsupported EXRULE parm: "+parm)
                exrulevals.append(value)
            elif name == "EXDATE":
                exdatevals.extend(
                    self._parse_date_value(value, parms,
                                           TZID_NAMES, ignoretz,
                                           tzids, tzinfos)
                )
            elif name == "DTSTART":
                dtvals = self._parse_date_value(value, parms, TZID_NAMES,
                                                ignoretz, tzids, tzinfos)
                if len(dtvals) != 1:
                    raise ValueError("Multiple DTSTART values specified:" +
                                     value)
                dtstart = dtvals[0]
            else:
                raise ValueError("unsupported property: "+name)
        if (forceset or len(rrulevals) > 1 or rdatevals
                or exrulevals or exdatevals):
            if not parser and (rdatevals or exdatevals):
                from dateutil import parser
            rset = rruleset(cache=cache)
            for value in rrulevals:
                rset.rrule(self._parse_rfc_rrule(value, dtstart=dtstart,
                                                 ignoretz=ignoretz,
                                                 tzinfos=tzinfos))
            for value in rdatevals:
                for datestr in value.split(','):
                    rset.rdate(parser.parse(datestr,
                                            ignoretz=ignoretz,
                                            tzinfos=tzinfos))
            for value in exrulevals:
                rset.exrule(self._parse_rfc_rrule(value, dtstart=dtstart,
                                                  ignoretz=ignoretz,
                                                  tzinfos=tzinfos))
            for value in exdatevals:
                rset.exdate(value)
            if compatible and dtstart:
                rset.rdate(dtstart)
            return rset
        else:
            return self._parse_rfc_rrule(rrulevals[0],
                                         dtstart=dtstart,
                                         cache=cache,
                                         ignoretz=ignoretz,
                                         tzinfos=tzinfos)

def __init__(self, stdabbr, stdoffset=None,
             dstabbr=None, dstoffset=None,
             start=None, end=None):

    global relativedelta
    from dateutil import relativedelta

    self._std_abbr = stdabbr
    self._dst_abbr = dstabbr

    try:
        stdoffset = stdoffset.total_seconds()
    except (TypeError, AttributeError):
        pass

    try:
        dstoffset = dstoffset.total_seconds()
    except (TypeError, AttributeError):
        pass

    if stdoffset is not None:
        self._std_offset = datetime.timedelta(seconds=stdoffset)
    else:
        self._std_offset = ZERO

    if dstoffset is not None:
        self._dst_offset = datetime.timedelta(seconds=dstoffset)
    elif dstabbr and stdoffset is not None:
        self._dst_offset = self._std_offset + datetime.timedelta(hours=+1)
    else:
        self._dst_offset = ZERO

    if dstabbr and start is None:
        self._start_delta = relativedelta.relativedelta(
            hours=+2, month=4, day=1, weekday=relativedelta.SU(+1))
    else:
        self._start_delta = start

    if dstabbr and end is None:
        self._end_delta = relativedelta.relativedelta(
            hours=+1, month=10, day=31, weekday=relativedelta.SU(-1))
    else:
        self._end_delta = end

    self._dst_base_offset_ = self._dst_offset - self._std_offset
    self.hasdst = bool(self._start_delta)

def _parse_rfc(self, s):
    lines = s.splitlines()
    if not lines:
        raise ValueError("empty string")

    # Unfold
    i = 0
    while i < len(lines):
        line = lines[i].rstrip()
        if not line:
            del lines[i]
        elif i > 0 and line[0] == " ":
            lines[i-1] += line[1:]
            del lines[i]
        else:
            i += 1

    tzid = None
    comps = []
    invtz = False
    comptype = None
    for line in lines:
        if not line:
            continue
        name, value = line.split(':', 1)
        parms = name.split(';')
        if not parms:
            raise ValueError("empty property name")
        name = parms[0].upper()
        parms = parms[1:]
        if invtz:
            if name == "BEGIN":
                if value in ("STANDARD", "DAYLIGHT"):
                    # Process component
                    pass
                else:
                    raise ValueError("unknown component: "+value)
                comptype = value
                founddtstart = False
                tzoffsetfrom = None
                tzoffsetto = None
                rrulelines = []
                tzname = None
            elif name == "END":
                if value == "VTIMEZONE":
                    if comptype:
                        raise ValueError("component not closed: "+comptype)
                    if not tzid:
                        raise ValueError("mandatory TZID not found")
                    if not comps:
                        raise ValueError(
                            "at least one component is needed")
                    # Process vtimezone
                    self._vtz[tzid] = _tzicalvtz(tzid, comps)
                    invtz = False
                elif value == comptype:
                    if not founddtstart:
                        raise ValueError("mandatory DTSTART not found")
                    if tzoffsetfrom is None:
                        raise ValueError(
                            "mandatory TZOFFSETFROM not found")
                    if tzoffsetto is None:
                        raise ValueError(
                            "mandatory TZOFFSETFROM not found")
                    # Process component
                    rr = None
                    if rrulelines:
                        rr = rrule.rrulestr("\n".join(rrulelines),
                                            compatible=True,
                                            ignoretz=True,
                                            cache=True)
                    comp = _tzicalvtzcomp(tzoffsetfrom, tzoffsetto,
                                          (comptype == "DAYLIGHT"),
                                          tzname, rr)
                    comps.append(comp)
                    comptype = None
                else:
                    raise ValueError("invalid component end: "+value)
            elif comptype:
                if name == "DTSTART":
                    # DTSTART in VTIMEZONE takes a subset of valid RRULE
                    # values under RFC 5545.
                    for parm in parms:
                        if parm != 'VALUE=DATE-TIME':
                            msg = ('Unsupported DTSTART param in ' +
                                   'VTIMEZONE: ' + parm)
                            raise ValueError(msg)
                    rrulelines.append(line)
                    founddtstart = True
                elif name in ("RRULE", "RDATE", "EXRULE", "EXDATE"):
                    rrulelines.append(line)
                elif name == "TZOFFSETFROM":
                    if parms:
                        raise ValueError(
                            "unsupported %s parm: %s " % (name, parms[0]))
                    tzoffsetfrom = self._parse_offset(value)
                elif name == "TZOFFSETTO":
                    if parms:
                        raise ValueError(
                            "unsupported TZOFFSETTO parm: "+parms[0])
                    tzoffsetto = self._parse_offset(value)
                elif name == "TZNAME":
                    if parms:
                        raise ValueError(
                            "unsupported TZNAME parm: "+parms[0])
                    tzname = value
                elif name == "COMMENT":
                    pass
                else:
                    raise ValueError("unsupported property: "+name)
            else:
                if name == "TZID":
                    if parms:
                        raise ValueError(
                            "unsupported TZID parm: "+parms[0])
                    tzid = value
                elif name in ("TZURL", "LAST-MODIFIED", "COMMENT"):
                    pass
                else:
                    raise ValueError("unsupported property: "+name)
        elif name == "BEGIN" and value == "VTIMEZONE":
            tzid = None
            comps = []
            invtz = True

def __repr__(self):
    l = []
    for attr in ["years", "months", "days", "leapdays",
                 "hours", "minutes", "seconds", "microseconds"]:
        value = getattr(self, attr)
        if value:
            l.append("{attr}={value:+g}".format(attr=attr, value=value))
    for attr in ["year", "month", "day", "weekday",
                 "hour", "minute", "second", "microsecond"]:
        value = getattr(self, attr)
        if value is not None:
            l.append("{attr}={value}".format(attr=attr, value=repr(value)))
    return "{classname}({attrs})".format(classname=self.__class__.__name__,
                                         attrs=", ".join(l))

