def _parse_dst_start_end(dststr):
    date, *time = dststr.split("/", 1)
    date_type = date[:1]
    if date_type == "M":
        n_is_julian = False
        m = re.fullmatch(r"M(\d{1,2})\.(\d)\.(\d)", date, re.ASCII)
        if m is None:
            raise ValueError("Invalid dst start/end date: %s" % dststr)
        date_offset = tuple(map(int, m.groups()))
        offset = _CalendarOffset(*date_offset)
    else:
        if date_type == "J":
            n_is_julian = True
            date = date[1:]
        else:
            n_is_julian = False

        if re.fullmatch(r"\d{1,3}", date, re.ASCII) is None:
            raise ValueError("Invalid dst start/end date: %s" % dststr)
        doy = int(date)
        offset = _DayOffset(doy, n_is_julian)

    if time:
        offset.hour, offset.minute, offset.second = _parse_transition_time(
            time[0]
        )

    return offset

