def _validate_fromutc_inputs(f):
    """
    The CPython version of ``fromutc`` checks that the input is a ``datetime``
    object and that ``self`` is attached as its ``tzinfo``.
    """
    @wraps(f)
    def fromutc(self, dt):
        if not isinstance(dt, datetime):
            raise TypeError("fromutc() requires a datetime argument")
        if dt.tzinfo is not self:
            raise ValueError("dt.tzinfo is not self")

        return f(self, dt)

    return fromutc

def _eager_load_tzdata(self):
    try:
        import tzdata
    except ImportError as e:
        raise ImportError(
            "The tzdata module is required to use ZoneInfoFile; either add a dependency on tzdata or migrate away from dateutil.zoneinfo."
        ) from e

    zone_dict = {}

    for key in _tzdata_impl._load_tzdata_keys():
        with _tzdata_impl._load_tzdata(key) as f:
            zone_dict[key] = tzfile(f, key=key)

    self.zones = zone_dict
    self.metadata = {
        "metadata_version": "3.0",
        "tzversion": tzdata.IANA_VERSION,
    }

def __init__(self, instream):
    if isinstance(instream, (bytes, bytearray)):
        instream = instream.decode()

    if isinstance(instream, str):
        instream = StringIO(instream)
    elif getattr(instream, 'read', None) is None:
        raise TypeError('Parser must be a string or character stream, not '
                        '{itype}'.format(itype=instream.__class__.__name__))

    self.instream = instream
    self.charstack = []
    self.tokenstack = []
    self.eof = False

def _set_months(self, months):
    self.months = months
    if abs(self.months) > 11:
        s = _sign(self.months)
        div, mod = divmod(self.months * s, 12)
        self.months = mod * s
        self.years = div * s
    else:
        self.years = 0

def _parse_isodate_common(self, dt_str):
    len_str = len(dt_str)
    components = [1, 1, 1]

    if len_str < 4:
        raise ValueError('ISO string too short')

    # Year
    components[0] = self._parse_digits(dt_str, 0, 4)
    pos = 4
    if pos >= len_str:
        return components, pos

    has_sep = dt_str[pos:pos + 1] == self._DATE_SEP
    if has_sep:
        pos += 1

    # Month
    if len_str - pos < 2:
        raise ValueError('Invalid common month')

    components[1] = self._parse_digits(dt_str, pos, 2)
    pos += 2

    if pos >= len_str:
        if has_sep:
            return components, pos
        else:
            raise ValueError('Invalid ISO format')

    if has_sep:
        if dt_str[pos:pos + 1] != self._DATE_SEP:
            raise ValueError('Invalid separator in ISO string')
        pos += 1

    # Day
    if len_str - pos < 2:
        raise ValueError('Invalid common day')
    components[2] = self._parse_digits(dt_str, pos, 2)
    return components, pos + 2

