def rebuild(self, year, month):
    # Every mask is 7 days longer to handle cross-year weekly periods.
    rr = self.rrule
    if year != self.lastyear:
        self.yearlen = 365 + calendar.isleap(year)
        self.nextyearlen = 365 + calendar.isleap(year + 1)
        firstyday = datetime.date(year, 1, 1)
        self.yearordinal = firstyday.toordinal()
        self.yearweekday = firstyday.weekday()

        wday = datetime.date(year, 1, 1).weekday()
        if self.yearlen == 365:
            self.mmask = M365MASK
            self.mdaymask = MDAY365MASK
            self.nmdaymask = NMDAY365MASK
            self.wdaymask = WDAYMASK[wday:]
            self.mrange = M365RANGE
        else:
            self.mmask = M366MASK
            self.mdaymask = MDAY366MASK
            self.nmdaymask = NMDAY366MASK
            self.wdaymask = WDAYMASK[wday:]
            self.mrange = M366RANGE

        if not rr._byweekno:
            self.wnomask = None
        else:
            self.wnomask = [0]*(self.yearlen+7)
            # no1wkst = firstwkst = self.wdaymask.index(rr._wkst)
            no1wkst = firstwkst = (7-self.yearweekday+rr._wkst) % 7
            if no1wkst >= 4:
                no1wkst = 0
                # Number of days in the year, plus the days we got
                # from last year.
                wyearlen = self.yearlen+(self.yearweekday-rr._wkst) % 7
            else:
                # Number of days in the year, minus the days we
                # left in last year.
                wyearlen = self.yearlen-no1wkst
            div, mod = divmod(wyearlen, 7)
            numweeks = div+mod//4
            for n in rr._byweekno:
                if n < 0:
                    n += numweeks+1
                if not (0 < n <= numweeks):
                    continue
                if n > 1:
                    i = no1wkst+(n-1)*7
                    if no1wkst != firstwkst:
                        i -= 7-firstwkst
                else:
                    i = no1wkst
                for j in range(7):
                    self.wnomask[i] = 1
                    i += 1
                    if self.wdaymask[i] == rr._wkst:
                        break
            if 1 in rr._byweekno:
                # Check week number 1 of next year as well
                # TODO: Check -numweeks for next year.
                i = no1wkst+numweeks*7
                if no1wkst != firstwkst:
                    i -= 7-firstwkst
                if i < self.yearlen:
                    # If week starts in next year, we
                    # don't care about it.
                    for j in range(7):
                        self.wnomask[i] = 1
                        i += 1
                        if self.wdaymask[i] == rr._wkst:
                            break
            if no1wkst:
                # Check last week number of last year as
                # well. If no1wkst is 0, either the year
                # started on week start, or week number 1
                # got days from last year, so there are no
                # days from last year's last week number in
                # this year.
                if -1 not in rr._byweekno:
                    lyearweekday = datetime.date(year-1, 1, 1).weekday()
                    lno1wkst = (7-lyearweekday+rr._wkst) % 7
                    lyearlen = 365+calendar.isleap(year-1)
                    if lno1wkst >= 4:
                        lno1wkst = 0
                        lnumweeks = 52+(lyearlen +
                                        (lyearweekday-rr._wkst) % 7) % 7//4
                    else:
                        lnumweeks = 52+(self.yearlen-no1wkst) % 7//4
                else:
                    lnumweeks = -1
                if lnumweeks in rr._byweekno:
                    for i in range(no1wkst):
                        self.wnomask[i] = 1

    if (rr._bynweekday and (month != self.lastmonth or
                            year != self.lastyear)):
        ranges = []
        if rr._freq == YEARLY:
            if rr._bymonth:
                for month in rr._bymonth:
                    ranges.append(self.mrange[month-1:month+1])
            else:
                ranges = [(0, self.yearlen)]
        elif rr._freq == MONTHLY:
            ranges = [self.mrange[month-1:month+1]]
        if ranges:
            # Weekly frequency won't get here, so we may not
            # care about cross-year weekly periods.
            self.nwdaymask = [0]*self.yearlen
            for first, last in ranges:
                last -= 1
                for wday, n in rr._bynweekday:
                    if n < 0:
                        i = last+(n+1)*7
                        i -= (self.wdaymask[i]-wday) % 7
                    else:
                        i = first+(n-1)*7
                        i += (7-self.wdaymask[i]+wday) % 7
                    if first <= i <= last:
                        self.nwdaymask[i] = 1

    if rr._byeaster:
        self.eastermask = [0]*(self.yearlen+7)
        eyday = easter.easter(year).toordinal()-self.yearordinal
        for offset in rr._byeaster:
            self.eastermask[eyday+offset] = 1

    self.lastyear = year
    self.lastmonth = month

def __init__(self, rrule):
    for attr in self.__slots__:
        setattr(self, attr, None)
    self.rrule = rrule

def __iter__(self):
    if self._cache_complete:
        return iter(self._cache)
    elif self._cache is None:
        return self._iter()
    else:
        return self._iter_cached()

def __init__(self, fileobj):
    global rrule
    from dateutil import rrule

    if isinstance(fileobj, str):
        self._s = fileobj
        # ical should be encoded in UTF-8 with CRLF
        fileobj = open(fileobj, 'r')
    else:
        self._s = getattr(fileobj, 'name', repr(fileobj))
        fileobj = contextlib.nullcontext(fileobj)

    self._vtz = {}

    with fileobj as fobj:
        self._parse_rfc(fobj.read())

def _invalidate_cache(self):
    if self._cache is not None:
        self._cache = []
        self._cache_complete = False
        self._cache_gen = self._iter()

        if self._cache_lock.locked():
            self._cache_lock.release()

    self._len = None

def __call__(cls, name, offset):
    if isinstance(offset, timedelta):
        key = (name, offset.total_seconds())
    else:
        key = (name, offset)

    instance = cls.__instances.get(key, None)
    if instance is None:
        instance = cls.__instances.setdefault(key,
                                              cls.instance(name, offset))

    # This lock may not be necessary in Python 3. See GH issue #901
    with cls._cache_lock:
        cls.__strong_cache[key] = cls.__strong_cache.pop(key, instance)

        # Remove an item if the strong cache is overpopulated
        if len(cls.__strong_cache) > cls.__strong_cache_size:
            cls.__strong_cache.popitem(last=False)

    return instance

def __str__(self):
    try:
        return self.args[0] % self.args[1:]
    except (TypeError, IndexError):
        return super().__str__()

def _parse_rfc(self, s):
    lines = s.splitlines()
    if not lines:
        raise ValueError("empty string")

    # Unfold
    i = 0
    while i < len(lines):
        line = lines[i].rstrip()
        if not line:
            del lines[i]
        elif i > 0 and line[0] == " ":
            lines[i-1] += line[1:]
            del lines[i]
        else:
            i += 1

    tzid = None
    comps = []
    invtz = False
    comptype = None
    for line in lines:
        if not line:
            continue
        name, value = line.split(':', 1)
        parms = name.split(';')
        if not parms:
            raise ValueError("empty property name")
        name = parms[0].upper()
        parms = parms[1:]
        if invtz:
            if name == "BEGIN":
                if value in ("STANDARD", "DAYLIGHT"):
                    # Process component
                    pass
                else:
                    raise ValueError("unknown component: "+value)
                comptype = value
                founddtstart = False
                tzoffsetfrom = None
                tzoffsetto = None
                rrulelines = []
                tzname = None
            elif name == "END":
                if value == "VTIMEZONE":
                    if comptype:
                        raise ValueError("component not closed: "+comptype)
                    if not tzid:
                        raise ValueError("mandatory TZID not found")
                    if not comps:
                        raise ValueError(
                            "at least one component is needed")
                    # Process vtimezone
                    self._vtz[tzid] = _tzicalvtz(tzid, comps)
                    invtz = False
                elif value == comptype:
                    if not founddtstart:
                        raise ValueError("mandatory DTSTART not found")
                    if tzoffsetfrom is None:
                        raise ValueError(
                            "mandatory TZOFFSETFROM not found")
                    if tzoffsetto is None:
                        raise ValueError(
                            "mandatory TZOFFSETFROM not found")
                    # Process component
                    rr = None
                    if rrulelines:
                        rr = rrule.rrulestr("\n".join(rrulelines),
                                            compatible=True,
                                            ignoretz=True,
                                            cache=True)
                    comp = _tzicalvtzcomp(tzoffsetfrom, tzoffsetto,
                                          (comptype == "DAYLIGHT"),
                                          tzname, rr)
                    comps.append(comp)
                    comptype = None
                else:
                    raise ValueError("invalid component end: "+value)
            elif comptype:
                if name == "DTSTART":
                    # DTSTART in VTIMEZONE takes a subset of valid RRULE
                    # values under RFC 5545.
                    for parm in parms:
                        if parm != 'VALUE=DATE-TIME':
                            msg = ('Unsupported DTSTART param in ' +
                                   'VTIMEZONE: ' + parm)
                            raise ValueError(msg)
                    rrulelines.append(line)
                    founddtstart = True
                elif name in ("RRULE", "RDATE", "EXRULE", "EXDATE"):
                    rrulelines.append(line)
                elif name == "TZOFFSETFROM":
                    if parms:
                        raise ValueError(
                            "unsupported %s parm: %s " % (name, parms[0]))
                    tzoffsetfrom = self._parse_offset(value)
                elif name == "TZOFFSETTO":
                    if parms:
                        raise ValueError(
                            "unsupported TZOFFSETTO parm: "+parms[0])
                    tzoffsetto = self._parse_offset(value)
                elif name == "TZNAME":
                    if parms:
                        raise ValueError(
                            "unsupported TZNAME parm: "+parms[0])
                    tzname = value
                elif name == "COMMENT":
                    pass
                else:
                    raise ValueError("unsupported property: "+name)
            else:
                if name == "TZID":
                    if parms:
                        raise ValueError(
                            "unsupported TZID parm: "+parms[0])
                    tzid = value
                elif name in ("TZURL", "LAST-MODIFIED", "COMMENT"):
                    pass
                else:
                    raise ValueError("unsupported property: "+name)
        elif name == "BEGIN" and value == "VTIMEZONE":
            tzid = None
            comps = []
            invtz = True

def __truediv__(self, other):
    try:
        reciprocal = 1 / float(other)
    except TypeError:
        return NotImplemented

    return self.__mul__(reciprocal)

def rebuild(self, year, month):
    # Every mask is 7 days longer to handle cross-year weekly periods.
    rr = self.rrule
    if year != self.lastyear:
        self.yearlen = 365 + calendar.isleap(year)
        self.nextyearlen = 365 + calendar.isleap(year + 1)
        firstyday = datetime.date(year, 1, 1)
        self.yearordinal = firstyday.toordinal()
        self.yearweekday = firstyday.weekday()

        wday = datetime.date(year, 1, 1).weekday()
        if self.yearlen == 365:
            self.mmask = M365MASK
            self.mdaymask = MDAY365MASK
            self.nmdaymask = NMDAY365MASK
            self.wdaymask = WDAYMASK[wday:]
            self.mrange = M365RANGE
        else:
            self.mmask = M366MASK
            self.mdaymask = MDAY366MASK
            self.nmdaymask = NMDAY366MASK
            self.wdaymask = WDAYMASK[wday:]
            self.mrange = M366RANGE

        if not rr._byweekno:
            self.wnomask = None
        else:
            self.wnomask = [0]*(self.yearlen+7)
            # no1wkst = firstwkst = self.wdaymask.index(rr._wkst)
            no1wkst = firstwkst = (7-self.yearweekday+rr._wkst) % 7
            if no1wkst >= 4:
                no1wkst = 0
                # Number of days in the year, plus the days we got
                # from last year.
                wyearlen = self.yearlen+(self.yearweekday-rr._wkst) % 7
            else:
                # Number of days in the year, minus the days we
                # left in last year.
                wyearlen = self.yearlen-no1wkst
            div, mod = divmod(wyearlen, 7)
            numweeks = div+mod//4
            for n in rr._byweekno:
                if n < 0:
                    n += numweeks+1
                if not (0 < n <= numweeks):
                    continue
                if n > 1:
                    i = no1wkst+(n-1)*7
                    if no1wkst != firstwkst:
                        i -= 7-firstwkst
                else:
                    i = no1wkst
                for j in range(7):
                    self.wnomask[i] = 1
                    i += 1
                    if self.wdaymask[i] == rr._wkst:
                        break
            if 1 in rr._byweekno:
                # Check week number 1 of next year as well
                # TODO: Check -numweeks for next year.
                i = no1wkst+numweeks*7
                if no1wkst != firstwkst:
                    i -= 7-firstwkst
                if i < self.yearlen:
                    # If week starts in next year, we
                    # don't care about it.
                    for j in range(7):
                        self.wnomask[i] = 1
                        i += 1
                        if self.wdaymask[i] == rr._wkst:
                            break
            if no1wkst:
                # Check last week number of last year as
                # well. If no1wkst is 0, either the year
                # started on week start, or week number 1
                # got days from last year, so there are no
                # days from last year's last week number in
                # this year.
                if -1 not in rr._byweekno:
                    lyearweekday = datetime.date(year-1, 1, 1).weekday()
                    lno1wkst = (7-lyearweekday+rr._wkst) % 7
                    lyearlen = 365+calendar.isleap(year-1)
                    if lno1wkst >= 4:
                        lno1wkst = 0
                        lnumweeks = 52+(lyearlen +
                                        (lyearweekday-rr._wkst) % 7) % 7//4
                    else:
                        lnumweeks = 52+(self.yearlen-no1wkst) % 7//4
                else:
                    lnumweeks = -1
                if lnumweeks in rr._byweekno:
                    for i in range(no1wkst):
                        self.wnomask[i] = 1

    if (rr._bynweekday and (month != self.lastmonth or
                            year != self.lastyear)):
        ranges = []
        if rr._freq == YEARLY:
            if rr._bymonth:
                for month in rr._bymonth:
                    ranges.append(self.mrange[month-1:month+1])
            else:
                ranges = [(0, self.yearlen)]
        elif rr._freq == MONTHLY:
            ranges = [self.mrange[month-1:month+1]]
        if ranges:
            # Weekly frequency won't get here, so we may not
            # care about cross-year weekly periods.
            self.nwdaymask = [0]*self.yearlen
            for first, last in ranges:
                last -= 1
                for wday, n in rr._bynweekday:
                    if n < 0:
                        i = last+(n+1)*7
                        i -= (self.wdaymask[i]-wday) % 7
                    else:
                        i = first+(n-1)*7
                        i += (7-self.wdaymask[i]+wday) % 7
                    if first <= i <= last:
                        self.nwdaymask[i] = 1

    if rr._byeaster:
        self.eastermask = [0]*(self.yearlen+7)
        eyday = easter.easter(year).toordinal()-self.yearordinal
        for offset in rr._byeaster:
            self.eastermask[eyday+offset] = 1

    self.lastyear = year
    self.lastmonth = month

def _parse_rfc_rrule(self, line,
                     dtstart=None,
                     cache=False,
                     ignoretz=False,
                     tzinfos=None):
    if line.find(':') != -1:
        name, value = line.split(':')
        if name != "RRULE":
            raise ValueError("unknown parameter name")
    else:
        value = line
    rrkwargs = {}
    for pair in value.split(';'):
        name, value = pair.split('=')
        name = name.upper()
        value = value.upper()
        try:
            getattr(self, "_handle_"+name)(rrkwargs, name, value,
                                           ignoretz=ignoretz,
                                           tzinfos=tzinfos)
        except AttributeError:
            raise ValueError("unknown parameter '%s'" % name)
        except (KeyError, ValueError):
            raise ValueError("invalid '%s': %s" % (name, value))
    return rrule(dtstart=dtstart, cache=cache, **rrkwargs)

def __init__(self, rrule):
    for attr in self.__slots__:
        setattr(self, attr, None)
    self.rrule = rrule

def _parse_rfc(self, s):
    lines = s.splitlines()
    if not lines:
        raise ValueError("empty string")

    # Unfold
    i = 0
    while i < len(lines):
        line = lines[i].rstrip()
        if not line:
            del lines[i]
        elif i > 0 and line[0] == " ":
            lines[i-1] += line[1:]
            del lines[i]
        else:
            i += 1

    tzid = None
    comps = []
    invtz = False
    comptype = None
    for line in lines:
        if not line:
            continue
        name, value = line.split(':', 1)
        parms = name.split(';')
        if not parms:
            raise ValueError("empty property name")
        name = parms[0].upper()
        parms = parms[1:]
        if invtz:
            if name == "BEGIN":
                if value in ("STANDARD", "DAYLIGHT"):
                    # Process component
                    pass
                else:
                    raise ValueError("unknown component: "+value)
                comptype = value
                founddtstart = False
                tzoffsetfrom = None
                tzoffsetto = None
                rrulelines = []
                tzname = None
            elif name == "END":
                if value == "VTIMEZONE":
                    if comptype:
                        raise ValueError("component not closed: "+comptype)
                    if not tzid:
                        raise ValueError("mandatory TZID not found")
                    if not comps:
                        raise ValueError(
                            "at least one component is needed")
                    # Process vtimezone
                    self._vtz[tzid] = _tzicalvtz(tzid, comps)
                    invtz = False
                elif value == comptype:
                    if not founddtstart:
                        raise ValueError("mandatory DTSTART not found")
                    if tzoffsetfrom is None:
                        raise ValueError(
                            "mandatory TZOFFSETFROM not found")
                    if tzoffsetto is None:
                        raise ValueError(
                            "mandatory TZOFFSETFROM not found")
                    # Process component
                    rr = None
                    if rrulelines:
                        rr = rrule.rrulestr("\n".join(rrulelines),
                                            compatible=True,
                                            ignoretz=True,
                                            cache=True)
                    comp = _tzicalvtzcomp(tzoffsetfrom, tzoffsetto,
                                          (comptype == "DAYLIGHT"),
                                          tzname, rr)
                    comps.append(comp)
                    comptype = None
                else:
                    raise ValueError("invalid component end: "+value)
            elif comptype:
                if name == "DTSTART":
                    # DTSTART in VTIMEZONE takes a subset of valid RRULE
                    # values under RFC 5545.
                    for parm in parms:
                        if parm != 'VALUE=DATE-TIME':
                            msg = ('Unsupported DTSTART param in ' +
                                   'VTIMEZONE: ' + parm)
                            raise ValueError(msg)
                    rrulelines.append(line)
                    founddtstart = True
                elif name in ("RRULE", "RDATE", "EXRULE", "EXDATE"):
                    rrulelines.append(line)
                elif name == "TZOFFSETFROM":
                    if parms:
                        raise ValueError(
                            "unsupported %s parm: %s " % (name, parms[0]))
                    tzoffsetfrom = self._parse_offset(value)
                elif name == "TZOFFSETTO":
                    if parms:
                        raise ValueError(
                            "unsupported TZOFFSETTO parm: "+parms[0])
                    tzoffsetto = self._parse_offset(value)
                elif name == "TZNAME":
                    if parms:
                        raise ValueError(
                            "unsupported TZNAME parm: "+parms[0])
                    tzname = value
                elif name == "COMMENT":
                    pass
                else:
                    raise ValueError("unsupported property: "+name)
            else:
                if name == "TZID":
                    if parms:
                        raise ValueError(
                            "unsupported TZID parm: "+parms[0])
                    tzid = value
                elif name in ("TZURL", "LAST-MODIFIED", "COMMENT"):
                    pass
                else:
                    raise ValueError("unsupported property: "+name)
        elif name == "BEGIN" and value == "VTIMEZONE":
            tzid = None
            comps = []
            invtz = True

def append(self, val, label=None):
    if hasattr(val, '__len__'):
        if val.isdigit() and len(val) > 2:
            self.century_specified = True
            if label not in [None, 'Y']:  # pragma: no cover
                raise ValueError(label)
            label = 'Y'
    elif val > 100:
        self.century_specified = True
        if label not in [None, 'Y']:  # pragma: no cover
            raise ValueError(label)
        label = 'Y'

    super().append(int(val))

    if label == 'M':
        if self.has_month:
            raise ValueError('Month is already set')
        self.mstridx = len(self) - 1
    elif label == 'D':
        if self.has_day:
            raise ValueError('Day is already set')
        self.dstridx = len(self) - 1
    elif label == 'Y':
        if self.has_year:
            raise ValueError('Year is already set')
        self.ystridx = len(self) - 1

def _parse_rfc(self, s,
               dtstart=None,
               cache=False,
               unfold=False,
               forceset=False,
               compatible=False,
               ignoretz=False,
               tzids=None,
               tzinfos=None):
    global parser
    if compatible:
        forceset = True
        unfold = True

    TZID_NAMES = dict(map(
        lambda x: (x.upper(), x),
        re.findall('TZID=(?P<name>[^:]+):', s)
    ))
    s = s.upper()
    if not s.strip():
        raise ValueError("empty string")
    if unfold:
        lines = s.splitlines()
        i = 0
        while i < len(lines):
            line = lines[i].rstrip()
            if not line:
                del lines[i]
            elif i > 0 and line[0] == " ":
                lines[i-1] += line[1:]
                del lines[i]
            else:
                i += 1
    else:
        lines = s.split()
    if (not forceset and len(lines) == 1 and (s.find(':') == -1 or
                                              s.startswith('RRULE:'))):
        return self._parse_rfc_rrule(lines[0], cache=cache,
                                     dtstart=dtstart, ignoretz=ignoretz,
                                     tzinfos=tzinfos)
    else:
        rrulevals = []
        rdatevals = []
        exrulevals = []
        exdatevals = []
        for line in lines:
            if not line:
                continue
            if line.find(':') == -1:
                name = "RRULE"
                value = line
            else:
                name, value = line.split(':', 1)
            parms = name.split(';')
            if not parms:
                raise ValueError("empty property name")
            name = parms[0]
            parms = parms[1:]
            if name == "RRULE":
                for parm in parms:
                    if parm.startswith("X-"):
                        # Experimental random vendor features; safe to ignore
                        continue
                    raise ValueError("unsupported RRULE parm: " + parm)
                rrulevals.append(value)
            elif name == "RDATE":
                for parm in parms:
                    if parm != "VALUE=DATE-TIME":
                        raise ValueError("unsupported RDATE parm: "+parm)
                rdatevals.append(value)
            elif name == "EXRULE":
                for parm in parms:
                    raise ValueError("unsupported EXRULE parm: "+parm)
                exrulevals.append(value)
            elif name == "EXDATE":
                exdatevals.extend(
                    self._parse_date_value(value, parms,
                                           TZID_NAMES, ignoretz,
                                           tzids, tzinfos)
                )
            elif name == "DTSTART":
                dtvals = self._parse_date_value(value, parms, TZID_NAMES,
                                                ignoretz, tzids, tzinfos)
                if len(dtvals) != 1:
                    raise ValueError("Multiple DTSTART values specified:" +
                                     value)
                dtstart = dtvals[0]
            else:
                raise ValueError("unsupported property: "+name)
        if (forceset or len(rrulevals) > 1 or rdatevals
                or exrulevals or exdatevals):
            if not parser and (rdatevals or exdatevals):
                from dateutil import parser
            rset = rruleset(cache=cache)
            for value in rrulevals:
                rset.rrule(self._parse_rfc_rrule(value, dtstart=dtstart,
                                                 ignoretz=ignoretz,
                                                 tzinfos=tzinfos))
            for value in rdatevals:
                for datestr in value.split(','):
                    rset.rdate(parser.parse(datestr,
                                            ignoretz=ignoretz,
                                            tzinfos=tzinfos))
            for value in exrulevals:
                rset.exrule(self._parse_rfc_rrule(value, dtstart=dtstart,
                                                  ignoretz=ignoretz,
                                                  tzinfos=tzinfos))
            for value in exdatevals:
                rset.exdate(value)
            if compatible and dtstart:
                rset.rdate(dtstart)
            return rset
        else:
            return self._parse_rfc_rrule(rrulevals[0],
                                         dtstart=dtstart,
                                         cache=cache,
                                         ignoretz=ignoretz,
                                         tzinfos=tzinfos)

def weekday(self, name):
    try:
        return self._weekdays[name.lower()]
    except KeyError:
        pass
    return None

def __init__(self, freq, dtstart=None,
             interval=1, wkst=None, count=None, until=None, bysetpos=None,
             bymonth=None, bymonthday=None, byyearday=None, byeaster=None,
             byweekno=None, byweekday=None,
             byhour=None, byminute=None, bysecond=None,
             cache=False):
    super().__init__(cache)
    global easter
    if not dtstart:
        if until and until.tzinfo:
            dtstart = datetime.datetime.now(tz=until.tzinfo).replace(microsecond=0)
        else:
            dtstart = datetime.datetime.now().replace(microsecond=0)
    elif not isinstance(dtstart, datetime.datetime):
        dtstart = datetime.datetime.fromordinal(dtstart.toordinal())
    else:
        dtstart = dtstart.replace(microsecond=0)
    self._dtstart = dtstart
    self._tzinfo = dtstart.tzinfo
    self._freq = freq
    self._interval = interval
    self._count = count

    # Cache the original byxxx rules, if they are provided, as the _byxxx
    # attributes do not necessarily map to the inputs, and this can be
    # a problem in generating the strings. Only store things if they've
    # been supplied (the string retrieval will just use .get())
    self._original_rule = {}

    if until and not isinstance(until, datetime.datetime):
        until = datetime.datetime.fromordinal(until.toordinal())
    self._until = until

    if self._dtstart and self._until:
        if (self._dtstart.tzinfo is not None) != (self._until.tzinfo is not None):
            # According to RFC5545 Section 3.3.10:
            # https://tools.ietf.org/html/rfc5545#section-3.3.10
            #
            # > If the "DTSTART" property is specified as a date with UTC
            # > time or a date with local time and time zone reference,
            # > then the UNTIL rule part MUST be specified as a date with
            # > UTC time.
            raise ValueError(
                'RRULE UNTIL values must be specified in UTC when DTSTART '
                'is timezone-aware'
            )

    if count is not None and until:
        warn("Using both 'count' and 'until' is inconsistent with RFC 5545"
             " and has been deprecated in dateutil. Future versions will "
             "raise an error.", DeprecationWarning)

    if wkst is None:
        self._wkst = calendar.firstweekday()
    elif isinstance(wkst, int):
        self._wkst = wkst
    else:
        self._wkst = wkst.weekday

    if bysetpos is None:
        self._bysetpos = None
    elif isinstance(bysetpos, int):
        if bysetpos == 0 or not (-366 <= bysetpos <= 366):
            raise ValueError("bysetpos must be between 1 and 366, "
                             "or between -366 and -1")
        self._bysetpos = (bysetpos,)
    else:
        self._bysetpos = tuple(bysetpos)
        for pos in self._bysetpos:
            if pos == 0 or not (-366 <= pos <= 366):
                raise ValueError("bysetpos must be between 1 and 366, "
                                 "or between -366 and -1")

    if self._bysetpos:
        self._original_rule['bysetpos'] = self._bysetpos

    if (byweekno is None and byyearday is None and bymonthday is None and
            byweekday is None and byeaster is None):
        if freq == YEARLY:
            if bymonth is None:
                bymonth = dtstart.month
                self._original_rule['bymonth'] = None
            bymonthday = dtstart.day
            self._original_rule['bymonthday'] = None
        elif freq == MONTHLY:
            bymonthday = dtstart.day
            self._original_rule['bymonthday'] = None
        elif freq == WEEKLY:
            byweekday = dtstart.weekday()
            self._original_rule['byweekday'] = None

    # bymonth
    if bymonth is None:
        self._bymonth = None
    else:
        if isinstance(bymonth, int):
            bymonth = (bymonth,)

        self._bymonth = tuple(sorted(set(bymonth)))

        if 'bymonth' not in self._original_rule:
            self._original_rule['bymonth'] = self._bymonth

    # byyearday
    if byyearday is None:
        self._byyearday = None
    else:
        if isinstance(byyearday, int):
            byyearday = (byyearday,)

        self._byyearday = tuple(sorted(set(byyearday)))
        self._original_rule['byyearday'] = self._byyearday

    # byeaster
    if byeaster is not None:
        if not easter:
            from dateutil import easter
        if isinstance(byeaster, int):
            self._byeaster = (byeaster,)
        else:
            self._byeaster = tuple(sorted(byeaster))

        self._original_rule['byeaster'] = self._byeaster
    else:
        self._byeaster = None

    # bymonthday
    if bymonthday is None:
        self._bymonthday = ()
        self._bynmonthday = ()
    else:
        if isinstance(bymonthday, int):
            bymonthday = (bymonthday,)

        bymonthday = set(bymonthday)            # Ensure it's unique

        self._bymonthday = tuple(sorted(x for x in bymonthday if x > 0))
        self._bynmonthday = tuple(sorted(x for x in bymonthday if x < 0))

        # Storing positive numbers first, then negative numbers
        if 'bymonthday' not in self._original_rule:
            self._original_rule['bymonthday'] = tuple(
                itertools.chain(self._bymonthday, self._bynmonthday))

    # byweekno
    if byweekno is None:
        self._byweekno = None
    else:
        if isinstance(byweekno, int):
            byweekno = (byweekno,)

        self._byweekno = tuple(sorted(set(byweekno)))

        self._original_rule['byweekno'] = self._byweekno

    # byweekday / bynweekday
    if byweekday is None:
        self._byweekday = None
        self._bynweekday = None
    else:
        # If it's one of the valid non-sequence types, convert to a
        # single-element sequence before the iterator that builds the
        # byweekday set.
        if isinstance(byweekday, int) or hasattr(byweekday, "n"):
            byweekday = (byweekday,)

        self._byweekday = set()
        self._bynweekday = set()
        for wday in byweekday:
            if isinstance(wday, int):
                self._byweekday.add(wday)
            elif not wday.n or freq > MONTHLY:
                self._byweekday.add(wday.weekday)
            else:
                self._bynweekday.add((wday.weekday, wday.n))

        if not self._byweekday:
            self._byweekday = None
        elif not self._bynweekday:
            self._bynweekday = None

        if self._byweekday is not None:
            self._byweekday = tuple(sorted(self._byweekday))
            orig_byweekday = [weekday(x) for x in self._byweekday]
        else:
            orig_byweekday = ()

        if self._bynweekday is not None:
            self._bynweekday = tuple(sorted(self._bynweekday))
            orig_bynweekday = [weekday(*x) for x in self._bynweekday]
        else:
            orig_bynweekday = ()

        if 'byweekday' not in self._original_rule:
            self._original_rule['byweekday'] = tuple(itertools.chain(
                orig_byweekday, orig_bynweekday))

    # byhour
    if byhour is None:
        if freq < HOURLY:
            self._byhour = {dtstart.hour}
        else:
            self._byhour = None
    else:
        if isinstance(byhour, int):
            byhour = (byhour,)

        if freq == HOURLY:
            self._byhour = self.__construct_byset(start=dtstart.hour,
                                                  byxxx=byhour,
                                                  base=24)
        else:
            self._byhour = set(byhour)

        self._byhour = tuple(sorted(self._byhour))
        self._original_rule['byhour'] = self._byhour

    # byminute
    if byminute is None:
        if freq < MINUTELY:
            self._byminute = {dtstart.minute}
        else:
            self._byminute = None
    else:
        if isinstance(byminute, int):
            byminute = (byminute,)

        if freq == MINUTELY:
            self._byminute = self.__construct_byset(start=dtstart.minute,
                                                    byxxx=byminute,
                                                    base=60)
        else:
            self._byminute = set(byminute)

        self._byminute = tuple(sorted(self._byminute))
        self._original_rule['byminute'] = self._byminute

    # bysecond
    if bysecond is None:
        if freq < SECONDLY:
            self._bysecond = ((dtstart.second,))
        else:
            self._bysecond = None
    else:
        if isinstance(bysecond, int):
            bysecond = (bysecond,)

        self._bysecond = set(bysecond)

        if freq == SECONDLY:
            self._bysecond = self.__construct_byset(start=dtstart.second,
                                                    byxxx=bysecond,
                                                    base=60)
        else:
            self._bysecond = set(bysecond)

        self._bysecond = tuple(sorted(self._bysecond))
        self._original_rule['bysecond'] = self._bysecond

    if self._freq >= HOURLY:
        self._timeset = None
    else:
        self._timeset = []
        for hour in self._byhour:
            for minute in self._byminute:
                for second in self._bysecond:
                    self._timeset.append(
                        datetime.time(hour, minute, second,
                                      tzinfo=self._tzinfo))
        self._timeset.sort()
        self._timeset = tuple(self._timeset)

def __init__(self, genlist, gen):
    try:
        self.dt = next(gen)
        genlist.append(self)
    except StopIteration:
        pass
    self.genlist = genlist
    self.gen = gen

def __iter__(self):
    if self._cache_complete:
        return iter(self._cache)
    elif self._cache is None:
        return self._iter()
    else:
        return self._iter_cached()

def _invalidate_cache(self):
    if self._cache is not None:
        self._cache = []
        self._cache_complete = False
        self._cache_gen = self._iter()

        if self._cache_lock.locked():
            self._cache_lock.release()

    self._len = None

def _parse_rfc_rrule(self, line,
                     dtstart=None,
                     cache=False,
                     ignoretz=False,
                     tzinfos=None):
    if line.find(':') != -1:
        name, value = line.split(':')
        if name != "RRULE":
            raise ValueError("unknown parameter name")
    else:
        value = line
    rrkwargs = {}
    for pair in value.split(';'):
        name, value = pair.split('=')
        name = name.upper()
        value = value.upper()
        try:
            getattr(self, "_handle_"+name)(rrkwargs, name, value,
                                           ignoretz=ignoretz,
                                           tzinfos=tzinfos)
        except AttributeError:
            raise ValueError("unknown parameter '%s'" % name)
        except (KeyError, ValueError):
            raise ValueError("invalid '%s': %s" % (name, value))
    return rrule(dtstart=dtstart, cache=cache, **rrkwargs)

def between(self, after, before, inc=False, count=1):
    """ Returns all the occurrences of the rrule between after and before.
    The inc keyword defines what happens if after and/or before are
    themselves occurrences. With inc=True, they will be included in the
    list, if they are found in the recurrence set. """
    if self._cache_complete:
        gen = self._cache
    else:
        gen = self
    started = False
    l = []
    if inc:
        for i in gen:
            if i > before:
                break
            elif not started:
                if i >= after:
                    started = True
                    l.append(i)
            else:
                l.append(i)
    else:
        for i in gen:
            if i >= before:
                break
            elif not started:
                if i > after:
                    started = True
                    l.append(i)
            else:
                l.append(i)
    return l

def append(self, val, label=None):
    if hasattr(val, '__len__'):
        if val.isdigit() and len(val) > 2:
            self.century_specified = True
            if label not in [None, 'Y']:  # pragma: no cover
                raise ValueError(label)
            label = 'Y'
    elif val > 100:
        self.century_specified = True
        if label not in [None, 'Y']:  # pragma: no cover
            raise ValueError(label)
        label = 'Y'

    super().append(int(val))

    if label == 'M':
        if self.has_month:
            raise ValueError('Month is already set')
        self.mstridx = len(self) - 1
    elif label == 'D':
        if self.has_day:
            raise ValueError('Day is already set')
        self.dstridx = len(self) - 1
    elif label == 'Y':
        if self.has_year:
            raise ValueError('Year is already set')
        self.ystridx = len(self) - 1

def rebuild(self, year, month):
    # Every mask is 7 days longer to handle cross-year weekly periods.
    rr = self.rrule
    if year != self.lastyear:
        self.yearlen = 365 + calendar.isleap(year)
        self.nextyearlen = 365 + calendar.isleap(year + 1)
        firstyday = datetime.date(year, 1, 1)
        self.yearordinal = firstyday.toordinal()
        self.yearweekday = firstyday.weekday()

        wday = datetime.date(year, 1, 1).weekday()
        if self.yearlen == 365:
            self.mmask = M365MASK
            self.mdaymask = MDAY365MASK
            self.nmdaymask = NMDAY365MASK
            self.wdaymask = WDAYMASK[wday:]
            self.mrange = M365RANGE
        else:
            self.mmask = M366MASK
            self.mdaymask = MDAY366MASK
            self.nmdaymask = NMDAY366MASK
            self.wdaymask = WDAYMASK[wday:]
            self.mrange = M366RANGE

        if not rr._byweekno:
            self.wnomask = None
        else:
            self.wnomask = [0]*(self.yearlen+7)
            # no1wkst = firstwkst = self.wdaymask.index(rr._wkst)
            no1wkst = firstwkst = (7-self.yearweekday+rr._wkst) % 7
            if no1wkst >= 4:
                no1wkst = 0
                # Number of days in the year, plus the days we got
                # from last year.
                wyearlen = self.yearlen+(self.yearweekday-rr._wkst) % 7
            else:
                # Number of days in the year, minus the days we
                # left in last year.
                wyearlen = self.yearlen-no1wkst
            div, mod = divmod(wyearlen, 7)
            numweeks = div+mod//4
            for n in rr._byweekno:
                if n < 0:
                    n += numweeks+1
                if not (0 < n <= numweeks):
                    continue
                if n > 1:
                    i = no1wkst+(n-1)*7
                    if no1wkst != firstwkst:
                        i -= 7-firstwkst
                else:
                    i = no1wkst
                for j in range(7):
                    self.wnomask[i] = 1
                    i += 1
                    if self.wdaymask[i] == rr._wkst:
                        break
            if 1 in rr._byweekno:
                # Check week number 1 of next year as well
                # TODO: Check -numweeks for next year.
                i = no1wkst+numweeks*7
                if no1wkst != firstwkst:
                    i -= 7-firstwkst
                if i < self.yearlen:
                    # If week starts in next year, we
                    # don't care about it.
                    for j in range(7):
                        self.wnomask[i] = 1
                        i += 1
                        if self.wdaymask[i] == rr._wkst:
                            break
            if no1wkst:
                # Check last week number of last year as
                # well. If no1wkst is 0, either the year
                # started on week start, or week number 1
                # got days from last year, so there are no
                # days from last year's last week number in
                # this year.
                if -1 not in rr._byweekno:
                    lyearweekday = datetime.date(year-1, 1, 1).weekday()
                    lno1wkst = (7-lyearweekday+rr._wkst) % 7
                    lyearlen = 365+calendar.isleap(year-1)
                    if lno1wkst >= 4:
                        lno1wkst = 0
                        lnumweeks = 52+(lyearlen +
                                        (lyearweekday-rr._wkst) % 7) % 7//4
                    else:
                        lnumweeks = 52+(self.yearlen-no1wkst) % 7//4
                else:
                    lnumweeks = -1
                if lnumweeks in rr._byweekno:
                    for i in range(no1wkst):
                        self.wnomask[i] = 1

    if (rr._bynweekday and (month != self.lastmonth or
                            year != self.lastyear)):
        ranges = []
        if rr._freq == YEARLY:
            if rr._bymonth:
                for month in rr._bymonth:
                    ranges.append(self.mrange[month-1:month+1])
            else:
                ranges = [(0, self.yearlen)]
        elif rr._freq == MONTHLY:
            ranges = [self.mrange[month-1:month+1]]
        if ranges:
            # Weekly frequency won't get here, so we may not
            # care about cross-year weekly periods.
            self.nwdaymask = [0]*self.yearlen
            for first, last in ranges:
                last -= 1
                for wday, n in rr._bynweekday:
                    if n < 0:
                        i = last+(n+1)*7
                        i -= (self.wdaymask[i]-wday) % 7
                    else:
                        i = first+(n-1)*7
                        i += (7-self.wdaymask[i]+wday) % 7
                    if first <= i <= last:
                        self.nwdaymask[i] = 1

    if rr._byeaster:
        self.eastermask = [0]*(self.yearlen+7)
        eyday = easter.easter(year).toordinal()-self.yearordinal
        for offset in rr._byeaster:
            self.eastermask[eyday+offset] = 1

    self.lastyear = year
    self.lastmonth = month

def __init__(self, wkday, n=None):
    if n == 0:
        raise ValueError("Can't create weekday with n==0")

    super().__init__(wkday, n)

def __call__(cls, name, offset):
    if isinstance(offset, timedelta):
        key = (name, offset.total_seconds())
    else:
        key = (name, offset)

    instance = cls.__instances.get(key, None)
    if instance is None:
        instance = cls.__instances.setdefault(key,
                                              cls.instance(name, offset))

    # This lock may not be necessary in Python 3. See GH issue #901
    with cls._cache_lock:
        cls.__strong_cache[key] = cls.__strong_cache.pop(key, instance)

        # Remove an item if the strong cache is overpopulated
        if len(cls.__strong_cache) > cls.__strong_cache_size:
            cls.__strong_cache.popitem(last=False)

    return instance

def __getattr__(name):
    import importlib

    if name in __all__ or name == "zoneinfo":
        return importlib.import_module("." + name, __name__)
    raise AttributeError(
        "module {!r} has no attribute {!r}".format(__name__, name)
    )

def __iter__(self):
    if self._cache_complete:
        return iter(self._cache)
    elif self._cache is None:
        return self._iter()
    else:
        return self._iter_cached()

def _parse_rfc(self, s,
               dtstart=None,
               cache=False,
               unfold=False,
               forceset=False,
               compatible=False,
               ignoretz=False,
               tzids=None,
               tzinfos=None):
    global parser
    if compatible:
        forceset = True
        unfold = True

    TZID_NAMES = dict(map(
        lambda x: (x.upper(), x),
        re.findall('TZID=(?P<name>[^:]+):', s)
    ))
    s = s.upper()
    if not s.strip():
        raise ValueError("empty string")
    if unfold:
        lines = s.splitlines()
        i = 0
        while i < len(lines):
            line = lines[i].rstrip()
            if not line:
                del lines[i]
            elif i > 0 and line[0] == " ":
                lines[i-1] += line[1:]
                del lines[i]
            else:
                i += 1
    else:
        lines = s.split()
    if (not forceset and len(lines) == 1 and (s.find(':') == -1 or
                                              s.startswith('RRULE:'))):
        return self._parse_rfc_rrule(lines[0], cache=cache,
                                     dtstart=dtstart, ignoretz=ignoretz,
                                     tzinfos=tzinfos)
    else:
        rrulevals = []
        rdatevals = []
        exrulevals = []
        exdatevals = []
        for line in lines:
            if not line:
                continue
            if line.find(':') == -1:
                name = "RRULE"
                value = line
            else:
                name, value = line.split(':', 1)
            parms = name.split(';')
            if not parms:
                raise ValueError("empty property name")
            name = parms[0]
            parms = parms[1:]
            if name == "RRULE":
                for parm in parms:
                    if parm.startswith("X-"):
                        # Experimental random vendor features; safe to ignore
                        continue
                    raise ValueError("unsupported RRULE parm: " + parm)
                rrulevals.append(value)
            elif name == "RDATE":
                for parm in parms:
                    if parm != "VALUE=DATE-TIME":
                        raise ValueError("unsupported RDATE parm: "+parm)
                rdatevals.append(value)
            elif name == "EXRULE":
                for parm in parms:
                    raise ValueError("unsupported EXRULE parm: "+parm)
                exrulevals.append(value)
            elif name == "EXDATE":
                exdatevals.extend(
                    self._parse_date_value(value, parms,
                                           TZID_NAMES, ignoretz,
                                           tzids, tzinfos)
                )
            elif name == "DTSTART":
                dtvals = self._parse_date_value(value, parms, TZID_NAMES,
                                                ignoretz, tzids, tzinfos)
                if len(dtvals) != 1:
                    raise ValueError("Multiple DTSTART values specified:" +
                                     value)
                dtstart = dtvals[0]
            else:
                raise ValueError("unsupported property: "+name)
        if (forceset or len(rrulevals) > 1 or rdatevals
                or exrulevals or exdatevals):
            if not parser and (rdatevals or exdatevals):
                from dateutil import parser
            rset = rruleset(cache=cache)
            for value in rrulevals:
                rset.rrule(self._parse_rfc_rrule(value, dtstart=dtstart,
                                                 ignoretz=ignoretz,
                                                 tzinfos=tzinfos))
            for value in rdatevals:
                for datestr in value.split(','):
                    rset.rdate(parser.parse(datestr,
                                            ignoretz=ignoretz,
                                            tzinfos=tzinfos))
            for value in exrulevals:
                rset.exrule(self._parse_rfc_rrule(value, dtstart=dtstart,
                                                  ignoretz=ignoretz,
                                                  tzinfos=tzinfos))
            for value in exdatevals:
                rset.exdate(value)
            if compatible and dtstart:
                rset.rdate(dtstart)
            return rset
        else:
            return self._parse_rfc_rrule(rrulevals[0],
                                         dtstart=dtstart,
                                         cache=cache,
                                         ignoretz=ignoretz,
                                         tzinfos=tzinfos)

def _invalidate_cache(self):
    if self._cache is not None:
        self._cache = []
        self._cache_complete = False
        self._cache_gen = self._iter()

        if self._cache_lock.locked():
            self._cache_lock.release()

    self._len = None

def __repr__(self):
    args = ", ".join("'%s'" % arg for arg in self.args)
    return "%s(%s)" % (self.__class__.__name__, args)

def __repr__(self):
    l = []
    for attr in ["years", "months", "days", "leapdays",
                 "hours", "minutes", "seconds", "microseconds"]:
        value = getattr(self, attr)
        if value:
            l.append("{attr}={value:+g}".format(attr=attr, value=value))
    for attr in ["year", "month", "day", "weekday",
                 "hour", "minute", "second", "microsecond"]:
        value = getattr(self, attr)
        if value is not None:
            l.append("{attr}={value}".format(attr=attr, value=repr(value)))
    return "{classname}({attrs})".format(classname=self.__class__.__name__,
                                         attrs=", ".join(l))

def __init__(self, stdabbr, stdoffset=None,
             dstabbr=None, dstoffset=None,
             start=None, end=None):

    global relativedelta
    from dateutil import relativedelta

    self._std_abbr = stdabbr
    self._dst_abbr = dstabbr

    try:
        stdoffset = stdoffset.total_seconds()
    except (TypeError, AttributeError):
        pass

    try:
        dstoffset = dstoffset.total_seconds()
    except (TypeError, AttributeError):
        pass

    if stdoffset is not None:
        self._std_offset = datetime.timedelta(seconds=stdoffset)
    else:
        self._std_offset = ZERO

    if dstoffset is not None:
        self._dst_offset = datetime.timedelta(seconds=dstoffset)
    elif dstabbr and stdoffset is not None:
        self._dst_offset = self._std_offset + datetime.timedelta(hours=+1)
    else:
        self._dst_offset = ZERO

    if dstabbr and start is None:
        self._start_delta = relativedelta.relativedelta(
            hours=+2, month=4, day=1, weekday=relativedelta.SU(+1))
    else:
        self._start_delta = start

    if dstabbr and end is None:
        self._end_delta = relativedelta.relativedelta(
            hours=+1, month=10, day=31, weekday=relativedelta.SU(-1))
    else:
        self._end_delta = end

    self._dst_base_offset_ = self._dst_offset - self._std_offset
    self.hasdst = bool(self._start_delta)

def __repr__(self):
    args = ", ".join("'%s'" % arg for arg in self.args)
    return "%s(%s)" % (self.__class__.__name__, args)

def __truediv__(self, other):
    try:
        reciprocal = 1 / float(other)
    except TypeError:
        return NotImplemented

    return self.__mul__(reciprocal)

def __str__(self):
    try:
        return self.args[0] % self.args[1:]
    except (TypeError, IndexError):
        return super().__str__()

def _parse_transition_time(time_str):
    match = re.fullmatch(
        r"(?P<sign>[+-])?(?P<h>\d{1,3})(:(?P<m>\d{2})(:(?P<s>\d{2}))?)?",
        time_str,
        re.ASCII,
    )
    if match is None:
        raise ValueError("Invalid time: %s" % time_str)

    h, m, s = (int(v or 0) for v in map(match.group, ("h", "m", "s")))

    if h > 167:
        raise ValueError("Hour must be in [0, 167]: %s" % time_str)

    if match.group("sign") == "-":
        h, m, s = -h, -m, -s

    return h, m, s

def __repr__(self):
    return "%s(%s, %s)" % (self.__class__.__name__,
                           repr(self._name),
                           int(self._offset.total_seconds()))

def max_days_in_month(year: int, month: int) -> int:
    """Determines the number of days of a specific month in a specific year."""
    if month in (1, 3, 5, 7, 8, 10, 12):
        return 31
    if month in (4, 6, 9, 11):
        return 30
    if ((year % 400) == 0) or ((year % 100) != 0) and ((year % 4) == 0):
        return 29
    return 28

def _strfduration(tdt: Union[timedelta, Duration], format: str, yeardigits: int = 4) -> str:
    """This is the work method for timedelta and Duration instances.

    See strftime for more details.
    """

    def repl(match: re.Match[str]) -> str:
        """Lookup format command and return corresponding replacement."""
        if match.group(0) in STRF_D_MAP:
            return STRF_D_MAP[match.group(0)](tdt, yeardigits)
        elif match.group(0) == "%P":
            ret: list[str] = []
            if isinstance(tdt, Duration):
                if tdt.years:
                    ret.append("%sY" % abs(tdt.years))
                if tdt.months:
                    ret.append("%sM" % abs(tdt.months))
            usecs = abs((tdt.days * 24 * 60 * 60 + tdt.seconds) * 1000000 + tdt.microseconds)
            seconds, usecs = divmod(usecs, 1000000)
            minutes, seconds = divmod(seconds, 60)
            hours, minutes = divmod(minutes, 60)
            days, hours = divmod(hours, 24)
            if days:
                ret.append("%sD" % days)
            if hours or minutes or seconds or usecs:
                ret.append("T")
                if hours:
                    ret.append("%sH" % hours)
                if minutes:
                    ret.append("%sM" % minutes)
                if seconds or usecs:
                    if usecs:
                        ret.append(("%d.%06d" % (seconds, usecs)).rstrip("0"))
                    else:
                        ret.append("%d" % seconds)
                    ret.append("S")
            # at least one component has to be there.
            return "".join(ret) if ret else "0D"
        elif match.group(0) == "%p":
            return str(abs(tdt.days // 7)) + "W"
        return match.group(0)

    return re.sub("%d|%f|%H|%m|%M|%S|%W|%Y|%C|%%|%P|%p", repl, format)

def parse_datetime(datetimestring: str) -> datetime:
    """Parses ISO 8601 date-times into datetime.datetime objects.

    This function uses parse_date and parse_time to do the job, so it allows
    more combinations of date and time representations, than the actual
    ISO 8601:2004 standard allows.
    """
    try:
        datestring, timestring = datetimestring.split("T")
    except ValueError:
        raise ISO8601Error(
            "ISO 8601 time designator 'T' missing. Unable to"
            " parse datetime string %r" % datetimestring
        )
    tmpdate = parse_date(datestring)
    tmptime = parse_time(timestring)
    return datetime.combine(tmpdate, tmptime)

def __mul__(self, other: int) -> Duration:
    if isinstance(other, int):
        newduration = Duration(years=self.years * other, months=self.months * other)
        newduration.tdelta = self.tdelta * other
        return newduration
    return NotImplemented

def parse_date(
    datestring: str,
    yeardigits: int = 4,
    expanded: bool = False,
    defaultmonth: int = 1,
    defaultday: int = 1,
) -> date:
    """Parse an ISO 8601 date string into a datetime.date object.

    As the datetime.date implementation is limited to dates starting from
    0001-01-01, negative dates (BC) and year 0 can not be parsed by this
    method.

    For incomplete dates, this method chooses the first day for it. For
    instance if only a century is given, this method returns the 1st of
    January in year 1 of this century.

    supported formats: (expanded formats are shown with 6 digits for year)
      YYYYMMDD    +-YYYYYYMMDD      basic complete date
      YYYY-MM-DD  +-YYYYYY-MM-DD    extended complete date
      YYYYWwwD    +-YYYYYYWwwD      basic complete week date
      YYYY-Www-D  +-YYYYYY-Www-D    extended complete week date
      YYYYDDD     +-YYYYYYDDD       basic ordinal date
      YYYY-DDD    +-YYYYYY-DDD      extended ordinal date
      YYYYWww     +-YYYYYYWww       basic incomplete week date
      YYYY-Www    +-YYYYYY-Www      extended incomplete week date
      YYYMM       +-YYYYYYMM        basic incomplete month date
      YYY-MM      +-YYYYYY-MM       incomplete month date
      YYYY        +-YYYYYY          incomplete year date
      YY          +-YYYY            incomplete century date

    @param datestring: the ISO date string to parse
    @param yeardigits: how many digits are used to represent a year
    @param expanded: if True then +/- signs are allowed. This parameter
                     is forced to True, if yeardigits != 4

    @return: a datetime.date instance represented by datestring
    @raise ISO8601Error: if this function can not parse the datestring
    @raise ValueError: if datestring can not be represented by datetime.date
    """
    if yeardigits != 4:
        expanded = True
    isodates = build_date_regexps(yeardigits, expanded)
    for pattern in isodates:
        match = pattern.match(datestring)
        if match:
            groups = match.groupdict()
            # sign, century, year, month, week, day,
            # FIXME: negative dates not possible with python standard types
            sign = (groups["sign"] == "-" and -1) or 1
            if "century" in groups:
                return date(sign * (int(groups["century"]) * 100 + 1), defaultmonth, defaultday)
            if "month" not in groups:  # weekdate or ordinal date
                ret = date(sign * int(groups["year"]), 1, 1)
                if "week" in groups:
                    isotuple = ret.isocalendar()
                    if "day" in groups:
                        days = int(groups["day"] or 1)
                    else:
                        days = 1
                    # if first week in year, do weeks-1
                    return ret + timedelta(
                        weeks=int(groups["week"]) - (((isotuple[1] == 1) and 1) or 0),
                        days=-isotuple[2] + days,
                    )
                elif "day" in groups:  # ordinal date
                    return ret + timedelta(days=int(groups["day"]) - 1)
                else:  # year date
                    return ret.replace(month=defaultmonth, day=defaultday)
            # year-, month-, or complete date
            if "day" not in groups or groups["day"] is None:
                day = defaultday
            else:
                day = int(groups["day"])
            return date(sign * int(groups["year"]), int(groups["month"]) or defaultmonth, day)
    raise ISO8601Error("Unrecognised ISO 8601 date format: %r" % datestring)

def repl(match: re.Match[str]) -> str:
    """Lookup format command and return corresponding replacement."""
    if match.group(0) in STRF_D_MAP:
        return STRF_D_MAP[match.group(0)](tdt, yeardigits)
    elif match.group(0) == "%P":
        ret: list[str] = []
        if isinstance(tdt, Duration):
            if tdt.years:
                ret.append("%sY" % abs(tdt.years))
            if tdt.months:
                ret.append("%sM" % abs(tdt.months))
        usecs = abs((tdt.days * 24 * 60 * 60 + tdt.seconds) * 1000000 + tdt.microseconds)
        seconds, usecs = divmod(usecs, 1000000)
        minutes, seconds = divmod(seconds, 60)
        hours, minutes = divmod(minutes, 60)
        days, hours = divmod(hours, 24)
        if days:
            ret.append("%sD" % days)
        if hours or minutes or seconds or usecs:
            ret.append("T")
            if hours:
                ret.append("%sH" % hours)
            if minutes:
                ret.append("%sM" % minutes)
            if seconds or usecs:
                if usecs:
                    ret.append(("%d.%06d" % (seconds, usecs)).rstrip("0"))
                else:
                    ret.append("%d" % seconds)
                ret.append("S")
        # at least one component has to be there.
        return "".join(ret) if ret else "0D"
    elif match.group(0) == "%p":
