    try:
        toml_obj = tomli.loads(data)
    except (tomli.TOMLDecodeError, RecursionError):
        return
    except BaseException:
        print_err(data)
        raise

    try:
        recovered_data = tomli_w.dumps(toml_obj)
    except RecursionError:
        return
    except BaseException:
        print_err(data)
        raise

