def skip_until(
    src: str,
    pos: Pos,
    expect: str,
    *,
    error_on: frozenset[str],
    error_on_eof: bool,
) -> Pos:
    try:
        new_pos = src.index(expect, pos)
    except ValueError:
        new_pos = len(src)
        if error_on_eof:
            raise TOMLDecodeError(f"Expected {expect!r}", src, new_pos) from None

    if not error_on.isdisjoint(src[pos:new_pos]):
        while src[pos] not in error_on:
            pos += 1
        raise TOMLDecodeError(f"Found invalid character {src[pos]!r}", src, pos)
    return new_pos

def append_nest_to_list(self, key: Key) -> None:
    cont = self.get_or_create_nest(key[:-1])
    last_key = key[-1]
    if last_key in cont:
        list_ = cont[last_key]
        if not isinstance(list_, list):
            raise KeyError("An object other than list found behind this key")
        list_.append({})
    else:
        cont[last_key] = [{}]

def use_setuptools() -> None:
    pyproject_path = Path(__file__).parent.parent / "pyproject.toml"
    data = tomllib.loads(pyproject_path.read_bytes().decode())
    data["build-system"] = {
        "requires": ["setuptools>=77.0.3", "mypy[mypyc]>=1.15"],
        "build-backend": "setuptools.build_meta",
    }
    pyproject_path.write_bytes(tomli_w.dumps(data).encode())

def unset_all(self, key: Key) -> None:
    cont = self._flags
    for k in key[:-1]:
        if k not in cont:
            return
        cont = cont[k]["nested"]
    cont.pop(key[-1], None)

def get_or_create_nest(
    self,
    key: Key,
    *,
    access_lists: bool = True,
) -> dict[str, Any]:
    cont: Any = self.dict
    for k in key:
        if k not in cont:
            cont[k] = {}
        cont = cont[k]
        if access_lists and isinstance(cont, list):
            cont = cont[-1]
        if not isinstance(cont, dict):
            raise KeyError("There is no nest behind this key")
    return cont  # type: ignore[no-any-return]

